-- Seed the SAT question bank. Generated by tools/sat-import/generate-seed.mjs.
-- 273 questions, 24 diagnostic. Do not hand-edit; re-run the generator.

INSERT INTO sat_questions
  (id, skill_id, stem, explanation, answer_type, options, correct_index,
   accepted_answers, difficulty, irt_a, irt_b, irt_c, is_diagnostic, source)
VALUES
  ('arith-0001', 'arithmetic-percentages', 'What percentage of 300 is 75?', '\(\frac{75}{300} = 0.25 = 25\%\).', 'mc', '["25%","50%","75%","225%"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P4M1 Q2'),
  ('arith-0002', 'arithmetic-percentages', 'A fish swam a distance of 5,104 yards. How far did the fish swim, in miles? \((1 mile = 1,760 yards)\)', '\(\frac{5{,}104}{1{,}760} = 2.9\) miles.', 'mc', '["0.3","2.9","3,344","6,864"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P4M2 Q2'),
  ('arith-0003', 'arithmetic-percentages', 'On the first day of a semester, a film club has 90 members. Each day after the first day of the semester, 10 new members join the film club. If no members leave the film club, how many total members will the film club have 4 days after the first day of the semester?', 'Starting with 90 members and adding 10 per day for 4 days: \(90 + 10(4) = 90 + 40 = 130\).', 'mc', '["400","130","94","90"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M1 Q2'),
  ('arith-0004', 'arithmetic-percentages', 'The result of increasing the quantity \(x\) by 400% is 60. What is the value of \(x\)?', 'Increasing \(x\) by 400% gives \(x + 4x = 5x\). So \(5x = 60 \Rightarrow x = 12\).', 'mc', '["12","15","240","340"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q25'),
  ('arith-0005', 'arithmetic-percentages', 'What is 20% of 440?', '\(0.20 \times 440 = 88\).', 'mc', '["44","88","880","1,760"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M2 Q1'),
  ('arith-0006', 'arithmetic-percentages', 'In 2008, Zinah earned 14% more than in 2007, and in 2009 Zinah earned 4% more than in 2008. If Zinah earned \(y\) times as much in 2009 as in 2007, what is the value of \(y\)?', 'Earnings multiply by 1.14 then by 1.04: \(1.14 \times 1.04 = 1.1856\). So \(y = 1.1856\).', 'mc', '["0.5600","1.0056","1.1800","1.1856"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q22'),
  ('arith-0007', 'arithmetic-percentages', 'The ratio of the length of line segment \(XY\) to the length of line segment \(ZV\) is 6 to 1. If the length of line segment \(XY\) is 102 inches, what is the length, in inches, of line segment \(ZV\)?', 'The ratio \(XY:ZV = 6:1\), so \(ZV = \frac{102}{6} = 17\) inches.', 'mc', '["17","96","102","612"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q9'),
  ('arith-0008', 'arithmetic-percentages', 'Rectangle P has an area of 72 square inches. If a rectangle with an area of 20 square inches is removed from rectangle P, what is the area, in square inches, of the resulting figure?', 'Removing 20 square inches from 72 square inches leaves \(72 - 20 = 52\) square inches.', 'mc', '["92","84","80","52"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M1 Q2'),
  ('arith-0009', 'arithmetic-percentages', 'A total of 165 people contributed to a charity event as either a donor or a volunteer. 130 people contributed as a donor. How many people contributed as a volunteer?', 'The number of volunteers is \(165 - 130 = 35\).', 'mc', '["35","130","165","330"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M2 Q1'),
  ('arith-0010', 'arithmetic-percentages', 'There are 250 trees in a park. Of these trees, 6% are birch trees. How many birch trees are in the park?', '\(0.06 \times 250 = 15\) birch trees.', 'mc', '["6","15","75","244"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M2 Q2'),
  ('arith-0011', 'arithmetic-percentages', 'The number of raccoons in a 131-square-mile area is estimated to be 2,358. What is the estimated population density, in raccoons per square mile, of this area?', 'Population density is \(\frac{2{,}358}{131} = 18\) raccoons per square mile.', 'mc', '["18","131","149","2,376"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P7M2 Q4'),
  ('arith-0012', 'arithmetic-percentages', 'The speed of a vehicle is increasing at a rate of 7.3 meters per second squared. What is this rate, in miles per minute squared, rounded to the nearest tenth? \((Use 1 mile = 1,609 meters.)\)', 'Convert: \(7.3 \frac{\text{m}}{\text{s}^2} \times \frac{1 \text{ mile}}{1609 \text{ m}} \times \left(\frac{60 \text{ s}}{1 \text{ min}}\right)^2 = 7.3 \times \frac{3600}{1609} \approx 16.3\) miles per minute squared.', 'mc', '["0.3","16.3","195.8","220.4"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P7M2 Q26'),
  ('arith-0013', 'arithmetic-percentages', 'For a certain region, a table shows the average number of store employees in 2016 by type of store: warehouse store 365, department store 213, supermarket 130. Based on the table, how much greater was the average number of store employees in warehouse stores than in supermarkets?', '\(365 - 130 = 235\).', 'mc', '["83","152","235","495"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M2 Q2'),
  ('arith-0014', 'arithmetic-percentages', 'A bowl contains 20 ounces of water. When the bowl is uncovered, the amount of water in the bowl decreases by 1 ounce every 4 days. If 9 ounces of water remain in this bowl, for how many days has it been uncovered?', 'The water decreased by \(20 - 9 = 11\) ounces. At 1 ounce per 4 days, that is \(11 \times 4 = 44\) days.', 'mc', '["3","7","36","44"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q15'),
  ('arith-0015', 'arithmetic-percentages', 'Ty set a goal to walk at least 24 kilometers every day to prepare for a multiday hike. On a certain day, Ty plans to walk at an average speed of 4 kilometers per hour. What is the minimum number of hours Ty must walk on that day to fulfill the daily goal?', 'Time equals distance divided by speed: \(\frac{24}{4} = 6\) hours.', 'mc', '["4","6","20","24"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M1 Q3'),
  ('arith-0016', 'arithmetic-percentages', 'One gallon of stain will cover 170 square feet of a surface. A yard has a total fence area of \(w\) square feet. Which equation represents the total amount of stain \(S\), in gallons, needed to stain the fence in this yard twice?', 'Staining twice covers \(2w\) square feet. At 170 square feet per gallon, \(S = \frac{2w}{170} = \frac{w}{85}\).', 'mc', '["\\(S = \\frac{w}{170}\\)","\\(S = 170w\\)","\\(S = 340w\\)","\\(S = \\frac{w}{85}\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q25'),
  ('arith-0017', 'arithmetic-percentages', 'A certain town has an area of 4.36 square miles. What is the area, in square yards, of this town? \((1 mile = 1,760 yards)\)', '1 square mile = \(1{,}760^2 = 3{,}097{,}600\) square yards. So \(4.36 \times 3{,}097{,}600 = 13{,}505{,}536\) square yards.', 'mc', '["404","7,674","710,459","13,505,536"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P9M2 Q23'),
  ('arith-0018', 'arithmetic-percentages', 'The result of increasing the quantity \(x\) by 1,800% is 684. What is the value of \(x\)?', 'Increasing \(x\) by 1,800% multiplies it by \(1 + 18 = 19\), so \(19x = 684\), giving \(x = 36\).', 'mc', '["12,996","12,312","38","36"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M1 Q25'),
  ('arith-0019', 'arithmetic-percentages', 'An object''s speed is 64 yards per second. What is the object''s speed, in feet per second? \((1 yard = 3 feet)\)', 'Multiply by 3 feet per yard: \(64 \times 3 = 192\) feet per second.', 'mc', '["61","67","94","192"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P10M2 Q1'),
  ('arith-0020', 'arithmetic-percentages', 'Of 300,000 paper clips, 234,000 are size large. What percentage of the paper clips are size large?', '\(\frac{234{,}000}{300{,}000} = 0.78 = 78\%\).', 'mc', '["22%","33%","66%","78%"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P10M2 Q8'),
  ('alg-0001', 'algebra-equations', '\(\frac{x^2}{25} = 36\) What is a solution to the given equation?', 'Multiply both sides by 25: \(x^2 = 900\), so \(x = 30\).', 'mc', '["6","30","450","900"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P4M1 Q3'),
  ('alg-0002', 'algebra-equations', '3 more than 8 times a number \(x\) is equal to 83. Which equation represents this situation?', '8 times \(x\) is \(8x\), and 3 more than that is \(8x + 3\), which equals 83: \(8x + 3 = 83\).', 'mc', '["\\((3)(8)x = 83\\)","\\(8x = 83 + 3\\)","\\(3x + 8 = 83\\)","\\(8x + 3 = 83\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P4M1 Q4'),
  ('alg-0003', 'algebra-equations', '\(\frac{14x}{7y} = 2\sqrt{w + 19}\) The given equation relates the distinct positive real numbers \(w\), \(x\), and \(y\). Which equation correctly expresses \(w\) in terms of \(x\) and \(y\)?', 'Simplify \(\frac{14x}{7y} = \frac{2x}{y}\), so \(\frac{2x}{y} = 2\sqrt{w+19}\), giving \(\frac{x}{y} = \sqrt{w+19}\). Square: \(\left(\frac{x}{y}\right)^2 = w + 19\), so \(w = \left(\frac{x}{y}\right)^2 - 19\).', 'mc', '["\\(w = \\sqrt{\\frac{x}{y}} - 19\\)","\\(w = \\sqrt{\\frac{28x}{14y}} - 19\\)","\\(w = \\left(\\frac{x}{y}\\right)^2 - 19\\)","\\(w = \\left(\\frac{28x}{14y}\\right)^2 - 19\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M1 Q19'),
  ('alg-0004', 'algebra-equations', 'Which expression is equivalent to \(12x^3 - 5x^3\)?', 'Combine like terms with the same power: \(12x^3 - 5x^3 = 7x^3\).', 'mc', '["\\(7x^6\\)","\\(17x^3\\)","\\(7x^3\\)","\\(17x^6\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P4M2 Q3'),
  ('alg-0005', 'algebra-equations', 'The point \((8, 2)\) in the \(xy\)-plane is a solution to which of the following systems of inequalities?', 'At \((8, 2)\), both \(x = 8 > 0\) and \(y = 2 > 0\), so the point satisfies \(x > 0\) and \(y > 0\).', 'mc', '["\\(x > 0\\), \\(y > 0\\)","\\(x > 0\\), \\(y < 0\\)","\\(x < 0\\), \\(y > 0\\)","\\(x < 0\\), \\(y < 0\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M2 Q5'),
  ('alg-0006', 'algebra-equations', 'A moving truck can tow a trailer if the combined weight of the trailer and the boxes it contains is no more than 4,600 pounds. What is the maximum number of boxes this truck can tow in a trailer with a weight of 500 pounds if each box weighs 120 pounds?', 'The boxes can weigh at most \(4{,}600 - 500 = 4{,}100\) pounds. \(\frac{4{,}100}{120} \approx 34.2\), so the maximum whole number of boxes is 34.', 'mc', '["34","35","38","39"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M2 Q11'),
  ('alg-0007', 'algebra-equations', '\(-3x + 21px = 84\) In the given equation, \(p\) is a constant. The equation has no solution. What is the value of \(p\)?', 'Factor: \((-3 + 21p)x = 84\). For no solution, the coefficient of \(x\) must be 0: \(-3 + 21p = 0 \Rightarrow p = \frac{3}{21} = \frac{1}{7}\).', 'mc', '["0","\\(\\frac{1}{7}\\)","\\(\\frac{4}{3}\\)","4"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P4M2 Q17'),
  ('alg-0008', 'algebra-equations', 'The equation \(x + y = 1{,}440\) represents the number of minutes of daylight (between sunrise and sunset), \(x\), and the number of minutes of non-daylight, \(y\), on a particular day in Oak Park, Illinois. If this day has 670 minutes of daylight, how many minutes of non-daylight does it have?', 'Substitute \(x = 670\): \(670 + y = 1{,}440 \Rightarrow y = 770\) minutes of non-daylight.', 'mc', '["670","770","1,373","1,440"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M1 Q9'),
  ('alg-0009', 'algebra-equations', 'If \(4x - 28 = -24\), what is the value of \(x - 7\)?', 'Divide the equation \(4x - 28 = -24\) by 4: \(x - 7 = -6\).', 'mc', '["-24","-22","-6","-1"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M1 Q11'),
  ('alg-0010', 'algebra-equations', 'For a snowstorm in a certain town, the minimum rate of snowfall recorded was 0.6 inches per hour, and the maximum rate of snowfall recorded was 1.8 inches per hour. Which inequality is true for all values of \(s\), where \(s\) represents a rate of snowfall, in inches per hour, recorded for this snowstorm?', 'All recorded rates fall between the minimum 0.6 and maximum 1.8 inches per hour, so \(0.6 \le s \le 1.8\).', 'mc', '["\\(s \\ge 2.4\\)","\\(s \\ge 1.8\\)","\\(0 \\le s \\le 0.6\\)","\\(0.6 \\le s \\le 1.8\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q12'),
  ('alg-0011', 'algebra-equations', 'At a particular track meet, the ratio of coaches to athletes is 1 to 26. If there are \(x\) coaches at the track meet, which of the following expressions represents the number of athletes at the track meet?', 'There are 26 athletes for each coach, so with \(x\) coaches the number of athletes is \(26x\).', 'mc', '["\\(\\frac{x}{26}\\)","\\(26x\\)","\\(x + 26\\)","\\(\\frac{26}{x}\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M1 Q17'),
  ('alg-0012', 'algebra-equations', 'Kaylani used fabric measuring 5 yards in length to make each suit for a men''s choir. The relationship between the number of suits that Kaylani made, \(x\), and the total length of fabric that she purchased \(y\), in yards, is represented by the equation \(y - 5x = 6\). What is the best interpretation of 6 in this context?', 'Rewriting: \(y = 5x + 6\), where \(5x\) is the fabric used. The constant 6 is the extra fabric purchased beyond what was used, so Kaylani purchased 6 yards more than she used.', 'mc', '["Kaylani made 6 suits.","Kaylani purchased a total of 6 yards of fabric.","Kaylani used a total of 6 yards of fabric to make the suits.","Kaylani purchased 6 yards more fabric than she used to make the suits."]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q18'),
  ('alg-0013', 'algebra-equations', 'The function \(f\) is defined by \(f(x) = 4x - 3\). What is the value of \(f(10)\)?', '\(f(10) = 4(10) - 3 = 40 - 3 = 37\).', 'mc', '["-30","37","40","43"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M2 Q3'),
  ('alg-0014', 'algebra-equations', 'If \(4\sqrt{2x} = 16\), what is the value of \(6x\)?', 'Divide by 4: \(\sqrt{2x} = 4\). Square: \(2x = 16\), so \(x = 8\) and \(6x = 48\).', 'mc', '["24","48","72","96"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q18'),
  ('alg-0015', 'algebra-equations', '\(2x - y > 883\) For which of the following tables are all the values of \(x\) and their corresponding values of \(y\) solutions to the given inequality?', 'The inequality requires \(2x - y > 883\). Testing table D: \((442,0): 884 > 883\) ✓; \((441,-2): 882 + 2 = 884 > 883\) ✓; \((440,-4): 880 + 4 = 884 > 883\) ✓. All rows satisfy the inequality.', 'mc', '["Table A: \\((440, 0), (441, -2), (442, -4)\\)","Table B: \\((440, 0), (442, -2), (441, -4)\\)","Table C: \\((442, 0), (440, -2), (441, -4)\\)","Table D: \\((442, 0), (441, -2), (440, -4)\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M2 Q19'),
  ('alg-0016', 'algebra-equations', 'Which expression is equivalent to \(\frac{42a}{k} + 42ak\), where \(k > 0\)?', 'Write over a common denominator: \(\frac{42a}{k} + 42ak = \frac{42a + 42ak^2}{k} = \frac{42a(1 + k^2)}{k} = \frac{42a(k^2 + 1)}{k}\).', 'mc', '["\\(\\frac{84a}{k}\\)","\\(\\frac{84ak^2}{k}\\)","\\(\\frac{42a(k + 1)}{k}\\)","\\(\\frac{42a(k^2 + 1)}{k}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M2 Q23'),
  ('alg-0017', 'algebra-equations', '\((p + 3) + 8 = 10\) What value of \(p\) is the solution to the given equation?', '\((p + 3) + 8 = 10 \Rightarrow p + 11 = 10 \Rightarrow p = -1\).', 'mc', '["-1","5","15","21"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P6M1 Q1'),
  ('alg-0018', 'algebra-equations', 'During a portion of a flight, a small airplane''s cruising speed varied between 150 miles per hour and 170 miles per hour. Which inequality best represents this situation, where \(s\) is the cruising speed, in miles per hour, during this portion of the flight?', 'The speed stays between 150 and 170 miles per hour inclusive, so \(150 \le s \le 170\).', 'mc', '["\\(s \\le 20\\)","\\(s \\le 150\\)","\\(s \\le 170\\)","\\(150 \\le s \\le 170\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P6M1 Q4'),
  ('alg-0019', 'algebra-equations', 'A manager is responsible for ordering supplies for a shaved ice shop. The shop''s inventory starts with 4,500 paper cups, and the manager estimates that 70 of these paper cups are used each day. Based on this estimate, in how many days will the supply of paper cups reach 1,700?', 'The number used to reach 1,700 is \(4{,}500 - 1{,}700 = 2{,}800\). At 70 per day: \(2{,}800 \div 70 = 40\) days.', 'mc', '["20","40","60","80"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q10'),
  ('alg-0020', 'algebra-equations', '\(y > 4x + 8\) For which of the following tables are all the values of \(x\) and their corresponding values of \(y\) solutions to the given inequality?', 'The inequality requires \(y > 4x + 8\). Table A: at \(x=2\), \(4(2)+8=16\) and \(19>16\) ✓; at \(x=4\), \(24\) and \(30>24\) ✓; at \(x=6\), \(32\) and \(41>32\) ✓. All rows satisfy it.', 'mc', '["Table A: \\((2, 19), (4, 30), (6, 41)\\)","Table B: \\((2, 8), (4, 16), (6, 24)\\)","Table C: \\((2, 13), (4, 18), (6, 23)\\)","Table D: \\((2, 13), (4, 21), (6, 29)\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M1 Q11'),
  ('alg-0021', 'algebra-equations', '\(P = N(19 - C)\) The given equation relates the positive numbers \(P\), \(N\), and \(C\). Which equation correctly expresses \(C\) in terms of \(P\) and \(N\)?', 'Divide by \(N\): \(\frac{P}{N} = 19 - C\). Solve for \(C\): \(C = 19 - \frac{P}{N}\).', 'mc', '["\\(C = \\frac{19 + P}{N}\\)","\\(C = \\frac{19 - P}{N}\\)","\\(C = 19 + \\frac{P}{N}\\)","\\(C = 19 - \\frac{P}{N}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M1 Q17'),
  ('alg-0022', 'algebra-equations', 'The function \(f\) is defined by \(f(x) = 8x\). For what value of \(x\) does \(f(x) = 72\)?', '\(8x = 72 \Rightarrow x = 9\).', 'mc', '["8","9","64","80"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P6M2 Q1'),
  ('alg-0023', 'algebra-equations', '\(7(2x - 3) = 63\) Which equation has the same solution as the given equation?', 'Dividing both sides of \(7(2x - 3) = 63\) by 7 gives \(2x - 3 = 9\), which has the same solution.', 'mc', '["\\(2x - 3 = 9\\)","\\(2x - 3 = 56\\)","\\(2x - 21 = 63\\)","\\(2x - 21 = 70\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q10'),
  ('alg-0024', 'algebra-equations', 'The function \(f\) is defined by \(f(x) = a\sqrt{x + b}\), where \(a\) and \(b\) are constants. In the \(xy\)-plane, the graph of \(y = f(x)\) passes through the point \((-24, 0)\), and \(f(24) < 0\). Which of the following must be true?', 'Passing through \((-24, 0)\) gives \(\sqrt{-24 + b} = 0\), so \(b = 24\). Since \(f(24) = a\sqrt{48} < 0\), \(a < 0\). Thus \(a < 0 < 24 = b\), so \(a < b\).', 'mc', '["\\(f(0) = 24\\)","\\(f(0) = -24\\)","\\(a > b\\)","\\(a < b\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M2 Q24'),
  ('alg-0025', 'algebra-equations', '\(|p| + 61 = 65\) Which value is a solution to the given equation?', '\(|p| = 65 - 61 = 4\), so \(p = 4\) (or \(-4\)). Among the choices, 4 is a solution.', 'mc', '["\\(\\frac{65}{61}\\)","4","126","130"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M1 Q3'),
  ('alg-0026', 'algebra-equations', 'Lorenzo purchased a box of cereal and some strawberries at the grocery store. Lorenzo paid 2 dollars for the box of cereal and 1.90 dollars per pound for the strawberries. If Lorenzo paid a total of 9.60 dollars for the box of cereal and the strawberries, which of the following equations can be used to find \(p\), the number of pounds of strawberries Lorenzo purchased? (Assume there is no sales tax.)', 'The strawberries cost \(1.90p\) and the cereal costs 2 dollars, totaling 9.60 dollars: \(1.90p + 2 = 9.60\).', 'mc', '["\\(1.90p + 2 = 9.60\\)","\\(1.90p - 2 = 9.60\\)","\\(1.90 + 2p = 9.60\\)","\\(1.90 - 2p = 9.60\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M1 Q4'),
  ('alg-0027', 'algebra-equations', 'The function \(f\) is defined by \(f(x) = |x - 4x|\). What value of \(a\) satisfies \(f(5) - f(a) = -15\)?', '\(f(x) = |x - 4x| = |-3x| = 3|x|\). So \(f(5) = 15\), and \(15 - f(a) = -15 \Rightarrow f(a) = 30 \Rightarrow 3|a| = 30 \Rightarrow |a| = 10\). Among the choices, \(a = 10\).', 'mc', '["-20","5","10","45"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M1 Q16'),
  ('alg-0028', 'algebra-equations', '\(\frac{12}{n} - \frac{2}{t} = -\frac{2}{w}\) The given equation relates the variables \(n\), \(t\), and \(w\), where \(n > 0\), \(t > 0\), and \(w > t\). Which expression is equivalent to \(n\)?', 'Rewrite: \(\frac{12}{n} = \frac{2}{t} - \frac{2}{w} = \frac{2w - 2t}{tw} = \frac{2(w - t)}{tw}\). So \(n = \frac{12tw}{2(w - t)} = \frac{6tw}{w - t}\).', 'mc', '["\\(12tw\\)","\\(6(t - w)\\)","\\(\\frac{w - t}{6tw}\\)","\\(\\frac{6tw}{w - t}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M1 Q19'),
  ('alg-0029', 'algebra-equations', 'In a set of four consecutive odd integers, where the integers are ordered from least to greatest, the first integer is represented by \(x\). The product of 12 and the fourth odd integer is at most 26 less than the sum of the first and third odd integers. Which inequality represents this situation?', 'The four consecutive odd integers are \(x, x+2, x+4, x+6\). The fourth is \(x+6\), and the first and third are \(x\) and \(x+4\). "At most 26 less than the sum" gives \(12(x+6) \le [x + (x+4)] - 26\).', 'mc', '["\\(12(x + 6) \\le x + (x + 4) - 26\\)","\\(12(x + 6) \\ge 26 - (x + (x + 4))\\)","\\(12(x + 4) \\le x + (x + 3) - 26\\)","\\(12(x + 4) \\ge 26 - (x + (x + 3))\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M1 Q23'),
  ('alg-0030', 'algebra-equations', 'If \(8x = 6\), what is the value of \(72x\)?', '\(72x = 9(8x) = 9(6) = 54\).', 'mc', '["3","15","54","57"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M2 Q8'),
  ('alg-0031', 'algebra-equations', 'At a state fair, attendees can win tokens that are worth a different number of points depending on the shape. One attendee won \(S\) square tokens and \(C\) circle tokens worth a total of 1,120 points. The equation \(80S + 90C = 1{,}120\) represents this situation. How many more points is a circle token worth than a square token?', 'A square token is worth 80 points and a circle token 90 points. The difference is \(90 - 80 = 10\) points.', 'mc', '["950","90","80","10"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M2 Q11'),
  ('alg-0032', 'algebra-equations', '\(y < x\) \(x < 22\) For which of the following tables are all the values of \(x\) and their corresponding values of \(y\) solutions to the given system of inequalities?', 'The system needs \(y < x\) and \(x < 22\). Table A: all \(x\) values (19, 20, 21) are less than 22, and each \(y\) is less than its \(x\). Both conditions hold for all rows.', 'mc', '["Table A: \\((19, 18), (20, 19), (21, 20)\\)","Table B: \\((19, 20), (20, 21), (21, 22)\\)","Table C: \\((23, 22), (24, 23), (25, 24)\\)","Table D: \\((23, 24), (24, 25), (25, 26)\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M2 Q16'),
  ('alg-0033', 'algebra-equations', 'Which expression is equivalent to \((2x^2 + x - 9) + (x^2 + 6x + 1)\)?', 'Combine like terms: \((2x^2 + x^2) + (x + 6x) + (-9 + 1) = 3x^2 + 7x - 8\).', 'mc', '["\\(2x^2 + 7x + 10\\)","\\(2x^2 + 6x - 8\\)","\\(3x^2 + 7x - 10\\)","\\(3x^2 + 7x - 8\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M1 Q4'),
  ('alg-0034', 'algebra-equations', '\(f(x) = 4x + b\) For the linear function \(f\), \(b\) is a constant and \(f(7) = 28\). What is the value of \(b\)?', '\(f(7) = 4(7) + b = 28 + b = 28\), so \(b = 0\).', 'mc', '["0","1","4","7"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q8'),
  ('alg-0035', 'algebra-equations', 'The area \(A\), in square centimeters, of a rectangular cutting board can be represented by the expression \(w(w + 9)\), where \(w\) is the width, in centimeters, of the cutting board. Which expression represents the length, in centimeters, of the cutting board?', 'Area equals length times width. Since area is \(w(w + 9)\) and width is \(w\), the length is \((w + 9)\).', 'mc', '["\\(w(w + 9)\\)","\\(w\\)","9","\\((w + 9)\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q16'),
  ('alg-0036', 'algebra-equations', '\(p = \frac{k}{4j + 9}\) The given equation relates the distinct positive numbers \(p\), \(k\), and \(j\). Which equation correctly expresses \(4j + 9\) in terms of \(p\) and \(k\)?', 'From \(p = \frac{k}{4j+9}\), multiply both sides by \(4j+9\) and divide by \(p\): \(4j + 9 = \frac{k}{p}\).', 'mc', '["\\(4j + 9 = \\frac{k}{p}\\)","\\(4j + 9 = kp\\)","\\(4j + 9 = k - p\\)","\\(4j + 9 = \\frac{p}{k}\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q17'),
  ('alg-0037', 'algebra-equations', '\(y \le x + 7\) \(y \ge -2x - 1\) Which point \((x, y)\) is a solution to the given system of inequalities in the \(xy\)-plane?', 'Test \((14, 0)\): \(0 \le 14 + 7 = 21\) is true, and \(0 \ge -2(14) - 1 = -29\) is true. Both inequalities hold.', 'mc', '["\\((-14, 0)\\)","\\((0, -14)\\)","\\((0, 14)\\)","\\((14, 0)\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P8M1 Q22'),
  ('alg-0038', 'algebra-equations', 'If \(9(4 - 3x) + 2 = 8(4 - 3x) + 18\), what is the value of \(4 - 3x\)?', 'Let \(u = 4 - 3x\). Then \(9u + 2 = 8u + 18 \Rightarrow u = 16\).', 'mc', '["-16","-4","4","16"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q16'),
  ('alg-0039', 'algebra-equations', '\(16x + 30 = 190\) Which equation has the same solution as the given equation?', 'Subtract 30 from both sides: \(16x = 190 - 30 = 160\).', 'mc', '["\\(16x = 30\\)","\\(16x = 130\\)","\\(16x = 160\\)","\\(16x = 190\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M1 Q2'),
  ('alg-0040', 'algebra-equations', 'Which expression is equivalent to \(9x^2 + 5x\)?', 'Factor out the common factor \(x\): \(9x^2 + 5x = x(9x + 5)\).', 'mc', '["\\(x(9x + 5)\\)","\\(5x(9x + 1)\\)","\\(9x(x + 5)\\)","\\(x^2(9x + 5)\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M1 Q5'),
  ('alg-0041', 'algebra-equations', 'John paid a total of 165 dollars for a microscope by making a down payment of 37 dollars plus \(p\) monthly payments of 16 dollars each. Which of the following equations represents this situation?', 'The monthly payments total \(16p\) and the down payment is 37, summing to 165: \(16p + 37 = 165\).', 'mc', '["\\(16p - 37 = 165\\)","\\(37p - 16 = 165\\)","\\(16p + 37 = 165\\)","\\(37p + 16 = 165\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q9'),
  ('alg-0042', 'algebra-equations', '\(y - 57 = px\) The given equation relates the positive numbers \(p\), \(x\), and \(y\). Which equation correctly expresses \(y\) in terms of \(p\) and \(x\)?', 'Add 57 to both sides: \(y = px + 57\).', 'mc', '["\\(y = 57x + p\\)","\\(y = px + 57\\)","\\(y = 57px\\)","\\(y = \\frac{px}{57}\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q10'),
  ('alg-0043', 'algebra-equations', 'A wire with a length of 106 inches is cut into two parts. One part has a length of \(x\) inches, and the other part has a length of \(y\) inches. The value of \(x\) is 6 more than 4 times the value of \(y\). What is the value of \(x\)?', 'We have \(x + y = 106\) and \(x = 4y + 6\). Substitute: \(4y + 6 + y = 106 \Rightarrow 5y = 100 \Rightarrow y = 20\), so \(x = 4(20) + 6 = 86\).', 'mc', '["25","28","56","86"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q16'),
  ('alg-0044', 'algebra-equations', '\(f(x) = (x + 6)(x + 5)(x - 4)\) The function \(f\) is given. Which table of values represents \(y = f(x) - 3\)?', 'At \(x = -6, -5, 4\), each is a root of \(f\), so \(f(x) = 0\). Then \(y = f(x) - 3 = 0 - 3 = -3\) for all three, matching the table with \(y = -3, -3, -3\).', 'mc', '["At \\(x = -6, -5, 4\\): \\(y = -9, -8, 1\\)","At \\(x = -6, -5, 4\\): \\(y = -3, -3, -3\\)","At \\(x = -6, -5, 4\\): \\(y = -3, -2, 7\\)","At \\(x = -6, -5, 4\\): \\(y = 3, 3, 3\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M1 Q17'),
  ('alg-0045', 'algebra-equations', 'A landscaper uses a hose that puts \(88x\) ounces of water in a bucket in \(5y\) minutes. Which expression represents the number of ounces of water the hose puts in the bucket in \(9y\) minutes at this rate?', 'The rate is \(\frac{88x}{5y}\) ounces per minute. In \(9y\) minutes: \(\frac{88x}{5y} \times 9y = \frac{792x}{5}\).', 'mc', '["\\(\\frac{9x}{440}\\)","\\(\\frac{440x}{9}\\)","\\(\\frac{5x}{792}\\)","\\(\\frac{792x}{5}\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q18'),
  ('alg-0046', 'algebra-equations', '\(w + 7 = 357\) What value of \(w\) is the solution to the given equation?', 'Subtract 7 from both sides: \(w = 357 - 7 = 350\).', 'mc', '["51","350","364","3,577"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M2 Q1'),
  ('alg-0047', 'algebra-equations', 'Which expression is equivalent to \(16(x + 15)\)?', 'Distribute: \(16(x + 15) = 16x + 240\).', 'mc', '["\\(16x + 31\\)","\\(16x + 240\\)","\\(16x + 1\\)","\\(16x + 15\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M2 Q2'),
  ('alg-0048', 'algebra-equations', 'Which expression is equivalent to \(\frac{y + 12}{x - 8} + \frac{y(x - 8)}{x^2y - 8xy}\)?', 'Note \(x^2y - 8xy = xy(x - 8)\), so the second fraction is \(\frac{y(x-8)}{xy(x-8)} = \frac{1}{x}\). Adding: \(\frac{y+12}{x-8} + \frac{1}{x} = \frac{x(y+12) + (x-8)}{x(x-8)} = \frac{xy + 12x + x - 8}{x^2 - 8x}\). Multiplying numerator and denominator by \(y\) to match form gives \(\frac{xy^2 + 13xy - 8y}{x^2y - 8xy}\).', 'mc', '["\\(\\frac{xy + y + 4}{x^3y - 16x^2y + 64xy}\\)","\\(\\frac{xy + 9y + 12}{x^2y - 8xy + x - 8}\\)","\\(\\frac{xy^2 + 13xy - 8y}{x^2y - 8xy}\\)","\\(\\frac{xy^2 + 13xy - 8y}{x^3y - 16x^2y + 64xy}\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M2 Q25'),
  ('alg-0049', 'algebra-equations', 'The total cost, in dollars, to rent a surfboard consists of a 25 dollar service fee and a 10 dollar per hour rental fee. A person rents a surfboard for \(t\) hours and intends to spend a maximum of 75 dollars to rent the surfboard. Which inequality represents this situation?', 'The cost is a fixed 25 dollar fee plus 10 dollars per hour, giving \(25 + 10t\), which must be at most 75: \(25 + 10t \le 75\).', 'mc', '["\\(10t \\le 75\\)","\\(10 + 25t \\le 75\\)","\\(25t \\le 75\\)","\\(25 + 10t \\le 75\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P10M1 Q3'),
  ('alg-0050', 'algebra-equations', 'If \(4x + 2 = 12\), what is the value of \(16x + 8\)?', 'Notice \(16x + 8 = 4(4x + 2) = 4(12) = 48\).', 'mc', '["40","48","56","60"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P10M1 Q10'),
  ('alg-0051', 'algebra-equations', 'A window repair specialist charges 220 dollars for the first two hours of repair plus an hourly fee for each additional hour. The total cost for 5 hours of repair is 400 dollars. Which function \(f\) gives the total cost, in dollars, for \(x\) hours of repair, where \(x \ge 2\)?', 'For 5 hours, the 3 additional hours cost \(400 - 220 = 180\) dollars, so the hourly fee is \(\frac{180}{3} = 60\) dollars. The cost is \(220 + 60(x - 2) = 60x + 100\).', 'mc', '["\\(f(x) = 60x + 100\\)","\\(f(x) = 60x + 220\\)","\\(f(x) = 80x\\)","\\(f(x) = 80x + 220\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M1 Q26'),
  ('alg-0052', 'algebra-equations', '\(7m = 2(n + p)\) The given equation relates the positive numbers \(m\), \(n\), and \(p\). Which equation correctly gives \(m\) in terms of \(n\) and \(p\)?', 'Divide both sides by 7: \(m = \frac{2(n + p)}{7}\).', 'mc', '["\\(m = \\frac{2(n + p)}{7}\\)","\\(m = 2(n + p)\\)","\\(m = 2(n + p) - 7\\)","\\(m = 2 - n - p - 7\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q5'),
  ('alg-0053', 'algebra-equations', '\(66x = 66x\) How many solutions does the given equation have?', 'The equation is true for every value of \(x\), so it has infinitely many solutions.', 'mc', '["Exactly one","Exactly two","Infinitely many","Zero"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q12'),
  ('alg-0054', 'algebra-equations', 'Which expression is equivalent to \(\frac{8x(x - 7) - 3(x - 7)}{2x - 14}\), where \(x > 7\)?', 'Factor the numerator: \(8x(x-7) - 3(x-7) = (x-7)(8x-3)\). The denominator is \(2x - 14 = 2(x-7)\). Cancel \((x-7)\): \(\frac{(x-7)(8x-3)}{2(x-7)} = \frac{8x-3}{2}\).', 'mc', '["\\(\\frac{x - 7}{5}\\)","\\(\\frac{8x - 3}{2}\\)","\\(\\frac{8x^2 - 3x - 14}{2x - 14}\\)","\\(\\frac{8x^2 - 3x - 77}{2x - 14}\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M2 Q17'),
  ('alg-0055', 'algebra-equations', '\(4x + 1 = 33\) Which equation has the same solution as the given equation?', 'Subtract 1 from both sides of \(4x + 1 = 33\) to get \(4x = 32\), which has the same solution.', 'mc', '["\\(4x = 32\\)","\\(4x = 5\\)","\\(4x = 1\\)","\\(4x = -32\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P11M1 Q2'),
  ('alg-0056', 'algebra-equations', 'In a chess tournament, each participant earns 1 point for each game the participant plays that ends in a draw and 3 points for each game the participant wins. A certain participant in this tournament has earned 41 points. Which equation represents this situation, where \(d\) represents the number of games this participant has played that ended in a draw and \(w\) represents the number of games this participant has won?', 'Draws contribute \(d\) points (1 each) and wins contribute \(3w\) points (3 each), totaling 41: \(d + 3w = 41\).', 'mc', '["\\(d + 3w = 41\\)","\\(3d + w = 41\\)","\\(d + \\frac{w}{3} = 41\\)","\\(\\frac{d}{3} + w = 41\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q8'),
  ('alg-0057', 'algebra-equations', 'The function \(g\) is defined by \(g(x) = \sqrt{x} + 300\). What is the value of \(g(x)\) when \(x = 81\)?', 'Substitute \(x = 81\): \(g(81) = \sqrt{81} + 300 = 9 + 300 = 309\).', 'mc', '["9","300","309","381"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q9'),
  ('alg-0058', 'algebra-equations', 'Which expression is equivalent to \(64t^2s^3 - 56t^3s\)?', 'The greatest common factor of \(64t^2s^3\) and \(56t^3s\) is \(8t^2s\)... factoring \(4t^2s\): \(64t^2s^3 = 4t^2s \cdot 16s^2\) and \(56t^3s = 4t^2s \cdot 14t\), giving \(4t^2s(16s^2 - 14t)\).', 'mc', '["\\(4ts(16s^2 - 14ts)\\)","\\(4ts(16t^2s^2 - 14t)\\)","\\(4t^2s(16ts - 14s)\\)","\\(4t^2s(16s^2 - 14t)\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q11'),
  ('alg-0059', 'algebra-equations', 'The cost to rent a bus from Company X is 950 dollars for the first 3 hours and an additional 50 dollars per hour for each hour after the first 3 hours. If the total cost to rent the bus from Company X for \(t\) hours, where \(t > 3\), is 1,150 dollars, which equation represents this situation?', 'The base cost is 950 dollars, plus 50 dollars for each hour beyond the first 3, which is \(50(t - 3)\). The total is \(950 + 50(t - 3) = 1{,}150\).', 'mc', '["\\(950(t - 3) + 50t = 1{,}150\\)","\\(950(3t) + 50t = 1{,}150\\)","\\(950 + 50(t - 3) = 1{,}150\\)","\\(950 + 50(3t) = 1{,}150\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M1 Q17'),
  ('alg-0060', 'algebra-equations', 'Which expression is equivalent to \(6x + 5x + 4y\)?', 'Combine the like \(x\)-terms: \(6x + 5x = 11x\), giving \(11x + 4y\).', 'mc', '["\\(15x\\)","\\(15y\\)","\\(11x + 4y\\)","\\(30x + 4y\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P11M2 Q1'),
  ('alg-0061', 'algebra-equations', 'The function \(f\) is defined by \(f(x) = 9(2x + 3)\). For what value of \(x\) does \(f(x) = 63\)?', 'Set \(9(2x + 3) = 63\). Divide by 9: \(2x + 3 = 7\), so \(2x = 4\) and \(x = 2\).', 'mc', '["2","5","7","30"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M2 Q5'),
  ('alg-0062', 'algebra-equations', 'Leo goes to a packing store to buy containers and tape. Leo has 15 dollars. Each container costs 1.87 dollars and each roll of tape costs 2.40 dollars. Which inequality represents the relationship between the number of containers, \(c\), and the number of rolls of tape, \(t\), Leo can buy?', 'Containers cost \(1.87c\) and tape costs \(2.40t\). The total spent cannot exceed 15 dollars: \(1.87c + 2.40t \le 15\).', 'mc', '["\\(1.87c + 2.40t \\le 15\\)","\\(1.87c + 2.40t \\ge 15\\)","\\(2.40c + 1.87t \\le 15\\)","\\(2.40c + 1.87t \\ge 15\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M2 Q8'),
  ('alg-0063', 'algebra-equations', 'For the polynomial function \(f\), the graph of \(y = f(x)\) in the \(xy\)-plane passes through the points \((-5, 0)\), \((1, 0)\), and \((4, 0)\). Which of the following must be a factor of \(f(x)\)?', 'An \(x\)-intercept at \((1, 0)\) means \(f(1) = 0\), so \((x - 1)\) is a factor. The other listed factors correspond to roots (\(-1, -4, 5\)) that are not intercepts of the graph.', 'mc', '["\\(x + 1\\)","\\(x + 4\\)","\\(x - 1\\)","\\(x - 5\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M2 Q16'),
  ('lin-0001', 'linear-functions', 'Hana deposited a fixed amount into her bank account each month. The function \(f(t) = 100 + 25t\) gives the amount, in dollars, in Hana''s bank account after \(t\) monthly deposits. What is the best interpretation of 25 in this context?', 'In \(f(t) = 100 + 25t\), the coefficient 25 is the rate of change per deposit, so the amount increases by 25 dollars with each monthly deposit.', 'mc', '["With each monthly deposit, the amount in Hana''s bank account increased by 25 dollars.","Before Hana made any monthly deposits, the amount in her bank account was 25 dollars.","After 1 monthly deposit, the amount in Hana''s bank account was 25 dollars.","Hana made a total of 25 monthly deposits."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M1 Q5'),
  ('lin-0002', 'linear-functions', 'Line \(t\) in the \(xy\)-plane has a slope of \(-\frac{1}{3}\) and passes through the point \((9, 10)\). Which equation defines line \(t\)?', 'Using point-slope with slope \(-\frac{1}{3}\) through \((9, 10)\): \(y = -\frac{1}{3}(x - 9) + 10 = -\frac{x}{3} + 3 + 10 = -\frac{x}{3} + 13\).', 'mc', '["\\(y = 13x - \\frac{1}{3}\\)","\\(y = 9x + 10\\)","\\(y = -\\frac{x}{3} + 10\\)","\\(y = -\\frac{x}{3} + 13\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P4M1 Q15'),
  ('lin-0003', 'linear-functions', 'The table shows selected values from function \(f\): \(f(-1) = 16\), \(f(0) = 17\), \(f(1) = 18\), \(f(2) = 19\). Which of the following is the best description of function \(f\)?', 'The values increase by a constant 1 for each unit increase in \(x\), which describes an increasing linear function.', 'mc', '["Decreasing linear","Increasing linear","Decreasing exponential","Increasing exponential"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q5'),
  ('lin-0004', 'linear-functions', 'Argon is placed inside a container with a constant volume. The graph shows the estimated pressure \(y\), in pounds per square inch (psi), of the argon when its temperature is \(x\) kelvins. What is the estimated pressure of the argon, in psi, when the temperature is 600 kelvins?', 'Reading the graph at \(x = 600\) kelvins, the line gives an estimated pressure of about 12 psi.', 'mc', '["6","12","300","600"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q2'),
  ('lin-0005', 'linear-functions', 'A veterinarian recommends that each day a certain rabbit should eat 25 calories per pound of the rabbit''s weight, plus an additional 11 calories. Which equation represents this situation, where \(c\) is the total number of calories the veterinarian recommends the rabbit should eat each day if the rabbit''s weight is \(x\) pounds?', '25 calories per pound is \(25x\), plus an additional 11 calories: \(c = 25x + 11\).', 'mc', '["\\(c = 25x\\)","\\(c = 36x\\)","\\(c = 11x + 25\\)","\\(c = 25x + 11\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q5'),
  ('lin-0006', 'linear-functions', 'Line \(r\) in the \(xy\)-plane has a slope of 4 and passes through the point \((0, 6)\). Which equation defines line \(r\)?', 'A line with slope 4 and \(y\)-intercept 6 is \(y = 4x + 6\).', 'mc', '["\\(y = -6x + 4\\)","\\(y = 6x + 4\\)","\\(y = 4x - 6\\)","\\(y = 4x + 6\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M2 Q8'),
  ('lin-0007', 'linear-functions', '\(f(x) = x + b\) For the linear function \(f\), \(b\) is a constant. When \(x = 0\), \(f(x) = 30\). What is the value of \(b\)?', '\(f(0) = 0 + b = b\), and \(f(0) = 30\), so \(b = 30\).', 'mc', '["-30","\\(-\\frac{1}{30}\\)","\\(\\frac{1}{30}\\)","30"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q8'),
  ('lin-0008', 'linear-functions', 'The relationship between two variables, \(x\) and \(y\), is linear. For every increase in the value of \(x\) by 1, the value of \(y\) increases by 8. When the value of \(x\) is 2, the value of \(y\) is 18. Which equation represents this relationship?', 'The slope is 8. Using \((2, 18)\): \(18 = 8(2) + b \Rightarrow b = 2\). So \(y = 8x + 2\).', 'mc', '["\\(y = 2x + 18\\)","\\(y = 2x + 8\\)","\\(y = 8x + 2\\)","\\(y = 3x + 26\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q16'),
  ('lin-0009', 'linear-functions', 'The table shows three values of \(x\) and their corresponding values of \(g(x)\), where \(g(x) = \frac{f(x)}{x + 3}\) and \(f\) is a linear function: \(g(-27) = 3\), \(g(-9) = 0\), \(g(21) = 5\). What is the \(y\)-intercept of the graph of \(y = f(x)\) in the \(xy\)-plane?', 'From \(g(x) = \frac{f(x)}{x+3}\), \(f(x) = g(x)(x+3)\). At \(x = -27\): \(f = 3(-24) = -72\); at \(x = -9\): \(f = 0\); at \(x = 21\): \(f = 5(24) = 120\). The line through \((-9, 0)\) and \((21, 120)\) has slope \(\frac{120}{30} = 4\), so \(f(x) = 4(x + 9) = 4x + 36\). The \(y\)-intercept is \((0, 36)\).', 'mc', '["\\((0, 36)\\)","\\((0, 12)\\)","\\((0, 4)\\)","\\((0, -9)\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M1 Q26'),
  ('lin-0010', 'linear-functions', 'The function \(f\) defined by \(f(t) = 14t + 9\) gives the estimated length, in inches, of a vine plant \(t\) months after Tavon purchased it. Which of the following is the best interpretation of 9 in this context?', 'The constant 9 is the value of \(f(0)\), the length at purchase (when \(t = 0\)), so the vine was estimated to be 9 inches when Tavon purchased it.', 'mc', '["Tavon will keep the vine plant for 9 months.","The vine plant is expected to grow 9 inches each month.","The vine plant is expected to grow to a maximum length of 9 inches.","The estimated length of the vine plant was 9 inches when Tavon purchased it."]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q11'),
  ('lin-0011', 'linear-functions', 'Line \(k\) is defined by \(y = 7x + \frac{1}{8}\). Line \(j\) is perpendicular to line \(k\) in the \(xy\)-plane. What is the slope of line \(j\)?', 'The slope of line \(k\) is 7. A perpendicular line has the negative reciprocal slope: \(-\frac{1}{7}\).', 'mc', '["-8","\\(-\\frac{1}{7}\\)","\\(\\frac{1}{8}\\)","7"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q18'),
  ('lin-0012', 'linear-functions', 'The table shows the linear relationship between the number of cars, \(c\), on a commuter train and the maximum number of passengers and crew, \(p\), that the train can carry: 3 cars gives 174, 5 cars gives 284, 10 cars gives 559. Which equation represents the linear relationship between \(c\) and \(p\)?', 'The slope is \(\frac{284 - 174}{5 - 3} = 55\). Using \((3, 174)\): \(p = 55c + b \Rightarrow 174 = 165 + b \Rightarrow b = 9\), so \(p = 55c + 9\), i.e. \(55c - p = -9\).', 'mc', '["\\(55c - p = -9\\)","\\(55c - p = 9\\)","\\(55p - c = -9\\)","\\(55p - c = 9\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M2 Q19'),
  ('lin-0013', 'linear-functions', 'The function \(f\) is defined by \(f(x) = \frac{1}{2}(x + 6)\). What is the value of \(f(4)\)?', '\(f(4) = \frac{1}{2}(4 + 6) = \frac{1}{2}(10) = 5\).', 'mc', '["20","12","10","5"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M1 Q10'),
  ('lin-0014', 'linear-functions', 'The table shows three values of \(x\) and their corresponding values of \(y\), where \(s\) is a constant: \((-2s, 24)\), \((-s, 21)\), \((s, 15)\). There is a linear relationship between \(x\) and \(y\). Which of the following equations represents this relationship?', 'The slope is \(\frac{15 - 21}{s - (-s)} = \frac{-6}{2s} = -\frac{3}{s}\). Using point \((-s, 21)\): \(y - 21 = -\frac{3}{s}(x + s)\), which rearranges to \(3x + sy = 18s\).', 'mc', '["\\(sx + 3y = 18s\\)","\\(3x + sy = 18s\\)","\\(3x + sy = 18\\)","\\(sx + 3y = 18\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M1 Q24'),
  ('lin-0015', 'linear-functions', 'The cost of renting a carpet cleaner is 52 dollars for the first day and 26 dollars for each additional day. Which of the following functions gives the cost \(C(d)\), in dollars, of renting the carpet cleaner for \(d\) days, where \(d\) is a positive integer?', 'The first day costs 52 dollars, and each of the remaining \(d - 1\) days costs 26 dollars: \(C(d) = 52 + 26(d - 1) = 26d + 26\).', 'mc', '["\\(C(d) = 26d + 26\\)","\\(C(d) = 26d + 52\\)","\\(C(d) = 52d - 26\\)","\\(C(d) = 52d + 78\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M1 Q26'),
  ('lin-0016', 'linear-functions', 'For the linear function \(f\), the table shows three values of \(x\) and their corresponding values of \(f(x)\): \((-4, 0)\), \(\left(-\frac{19}{5}, 1\right)\), \(\left(-\frac{18}{5}, 2\right)\). If \(h(x) = f(x) - 13\), which equation defines \(h\)?', 'The slope of \(f\) is \(\frac{1 - 0}{-\frac{19}{5} - (-4)} = \frac{1}{\frac{1}{5}} = 5\). Using \((-4, 0)\): \(f(x) = 5(x + 4) = 5x + 20\). Then \(h(x) = f(x) - 13 = 5x + 20 - 13 = 5x + 7\).', 'mc', '["\\(h(x) = 5x - 4\\)","\\(h(x) = 5x + 7\\)","\\(h(x) = 5x + 9\\)","\\(h(x) = 5x + 20\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M2 Q22'),
  ('lin-0017', 'linear-functions', 'The linear function \(g\) is defined by \(g(x) = b - 15x\), where \(b\) is a constant. If \(g(c + 7) = \frac{c}{4}\), where \(c\) is a constant, which of the following expressions represents the value of \(b\)?', '\(g(c + 7) = b - 15(c + 7) = b - 15c - 105\). Setting equal to \(\frac{c}{4}\): \(b = \frac{c}{4} + 15c + 105 = \frac{c + 60c}{4} + 105 = \frac{61c}{4} + 105\).', 'mc', '["\\(\\frac{15c}{4}\\)","\\(\\frac{19c}{4} + 7\\)","\\(\\frac{61c}{4} + 105\\)","\\(15c + 105\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P7M2 Q23'),
  ('lin-0018', 'linear-functions', 'A bus is traveling at a constant speed along a straight portion of road. The equation \(d = 30t\) gives the distance \(d\), in feet from a road marker, that the bus will be \(t\) seconds after passing the marker. How many feet from the marker will the bus be 2 seconds after passing the marker?', 'Substitute \(t = 2\): \(d = 30(2) = 60\) feet.', 'mc', '["30","32","60","90"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M1 Q1'),
  ('lin-0019', 'linear-functions', 'What is the equation of the line that passes through the point \((0, 5)\) and is parallel to the graph of \(y = 7x + 4\) in the \(xy\)-plane?', 'A parallel line has the same slope, 7. Passing through \((0, 5)\) gives \(y\)-intercept 5, so \(y = 7x + 5\).', 'mc', '["\\(y = 5x\\)","\\(y = 7x + 5\\)","\\(y = 7x\\)","\\(y = 5x + 7\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q10'),
  ('lin-0020', 'linear-functions', 'A scatterplot shows data that decreases as \(x\) increases, with points starting near \(y = 10\) at \(x = 1\) and dropping to near \(y = 1\) at \(x = 5\). Which of the following equations is the most appropriate linear model for the data shown in the scatterplot?', 'The data decreases, so the slope is negative, and the \(y\)-intercept is positive (near 10). This matches \(y = -1.9x + 10.1\).', 'mc', '["\\(y = -1.9x - 10.1\\)","\\(y = -1.9x + 10.1\\)","\\(y = 1.9x - 10.1\\)","\\(y = 1.9x + 10.1\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q11'),
  ('lin-0021', 'linear-functions', 'A line is graphed in the \(xy\)-plane passing through the origin region and crossing the \(y\)-axis at 5. What is the \(y\)-intercept of the line graphed?', 'The line crosses the \(y\)-axis at 5, so the \(y\)-intercept is \((0, 5)\).', 'mc', '["\\((-5, 0)\\)","\\((0, 0)\\)","\\((0, 5)\\)","\\((0, 9)\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P8M2 Q1'),
  ('lin-0022', 'linear-functions', 'Sean rents a tent at a cost of 11 dollars per day plus a one-time insurance fee of 10 dollars. Which equation represents the total cost \(c\), in dollars, to rent the tent with insurance for \(d\) days?', 'The daily cost is \(11d\) and the one-time fee is 10, so \(c = 11d + 10\).', 'mc', '["\\(c = 11(d + 10)\\)","\\(c = 10(d + 11)\\)","\\(c = 11d + 10\\)","\\(c = 10d + 11\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M2 Q4'),
  ('lin-0023', 'linear-functions', 'The function \(f\) is defined by \(f(x) = \frac{1}{10}x - 2\). What is the \(y\)-intercept of the graph of \(y = f(x)\) in the \(xy\)-plane?', 'The \(y\)-intercept occurs at \(x = 0\): \(f(0) = \frac{1}{10}(0) - 2 = -2\), so the point is \((0, -2)\).', 'mc', '["\\((-2, 0)\\)","\\((0, -2)\\)","\\(\\left(0, \\frac{1}{10}\\right)\\)","\\(\\left(\\frac{1}{10}, 0\\right)\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M2 Q8'),
  ('lin-0024', 'linear-functions', 'A producer is creating a video with a length of 70 minutes. The video will consist of segments that are 1 minute long and segments that are 3 minutes long. Which equation represents this situation, where \(x\) represents the number of 1-minute segments and \(y\) represents the number of 3-minute segments?', 'Each 1-minute segment contributes \(x\) minutes and each 3-minute segment contributes \(3y\) minutes, totaling 70: \(x + 3y = 70\).', 'mc', '["\\(4xy = 70\\)","\\(4(x + y) = 70\\)","\\(3x + y = 70\\)","\\(x + 3y = 70\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q9'),
  ('lin-0025', 'linear-functions', 'A certain township consists of a 5-hectare industrial park and a 24-hectare neighborhood. The total number of trees in the township is 4,529. The equation \(5x + 24y = 4{,}529\) represents this situation. Which of the following is the best interpretation of \(x\) in this context?', 'The term \(5x\) multiplies the 5 hectares of industrial park by \(x\), so \(x\) is the average number of trees per hectare in the industrial park.', 'mc', '["The average number of trees per hectare in the industrial park","The average number of trees per hectare in the neighborhood","The total number of trees in the industrial park","The total number of trees in the neighborhood"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M2 Q17'),
  ('lin-0026', 'linear-functions', 'A line in the \(xy\)-plane has a slope of \(\frac{1}{9}\) and passes through the point \((0, 14)\). Which equation represents this line?', 'With slope \(\frac{1}{9}\) and \(y\)-intercept 14 (from the point \((0, 14)\)): \(y = \frac{1}{9}x + 14\).', 'mc', '["\\(y = -\\frac{1}{9}x - 14\\)","\\(y = -\\frac{1}{9}x + 14\\)","\\(y = \\frac{1}{9}x - 14\\)","\\(y = \\frac{1}{9}x + 14\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q5'),
  ('lin-0027', 'linear-functions', 'A table shows three values of \(x\) and their corresponding values of \(y\): when \(x = 0\), \(y = 18\); when \(x = 1\), \(y = 13\); when \(x = 2\), \(y = 8\). There is a linear relationship between \(x\) and \(y\). Which of the following equations represents this relationship?', 'The \(y\)-intercept is 18 (at \(x = 0\)). The slope is \(\frac{13 - 18}{1 - 0} = -5\). So \(y = -5x + 18\).', 'mc', '["\\(y = 18x + 13\\)","\\(y = 18x + 18\\)","\\(y = -5x + 13\\)","\\(y = -5x + 18\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q8'),
  ('lin-0028', 'linear-functions', 'The function \(f\) is defined by \(f(x) = 7x - 84\). What is the \(x\)-intercept of the graph of \(y = f(x)\) in the \(xy\)-plane?', 'Set \(f(x) = 0\): \(7x - 84 = 0 \Rightarrow x = 12\), so the \(x\)-intercept is \((12, 0)\).', 'mc', '["\\((-12, 0)\\)","\\((-7, 0)\\)","\\((7, 0)\\)","\\((12, 0)\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q10'),
  ('lin-0029', 'linear-functions', '\(w(t) = 300 - 4t\) The function \(w\) models the volume of liquid, in milliliters, in a container \(t\) seconds after it begins draining from a hole at the bottom. According to the model, what is the predicted volume, in milliliters, draining from the container each second?', 'The coefficient of \(t\) is \(-4\), meaning the volume decreases by 4 milliliters each second, so 4 milliliters drains per second.', 'mc', '["300","296","75","4"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q12'),
  ('lin-0030', 'linear-functions', '\(y > 13x - 18\) For which of the following tables are all the values of \(x\) and their corresponding values of \(y\) solutions to the given inequality?', 'For each pair, check \(y > 13x - 18\). At \(x = 3\), need \(y > 21\); at \(x = 5\), need \(y > 47\); at \(x = 8\), need \(y > 86\). Only the table \((3, 26), (5, 52), (8, 91)\) satisfies all three: \(26 > 21\), \(52 > 47\), \(91 > 86\).', 'mc', '["\\((3, 21), (5, 47), (8, 86)\\)","\\((3, 26), (5, 42), (8, 86)\\)","\\((3, 16), (5, 42), (8, 81)\\)","\\((3, 26), (5, 52), (8, 91)\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M2 Q22'),
  ('lin-0031', 'linear-functions', '\(s = 40 + 3t\) The equation gives the speed \(s\), in miles per hour, of a certain car \(t\) seconds after it began to accelerate. What is the speed, in miles per hour, of the car 5 seconds after it began to accelerate?', 'Substitute \(t = 5\): \(s = 40 + 3(5) = 40 + 15 = 55\) miles per hour.', 'mc', '["40","43","45","55"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P10M1 Q5'),
  ('lin-0032', 'linear-functions', 'The function \(h\) is defined by \(h(x) = 4x + 28\). The graph of \(y = h(x)\) in the \(xy\)-plane has an \(x\)-intercept at \((a, 0)\) and a \(y\)-intercept at \((0, b)\), where \(a\) and \(b\) are constants. What is the value of \(a + b\)?', 'The \(x\)-intercept: \(0 = 4x + 28 \Rightarrow x = -7\), so \(a = -7\). The \(y\)-intercept: \(h(0) = 28\), so \(b = 28\). Then \(a + b = -7 + 28 = 21\).', 'mc', '["21","28","32","35"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q18'),
  ('lin-0033', 'linear-functions', '\(y < 5x + 6\) For which of the following tables are all the values of \(x\) and their corresponding values of \(y\) solutions to the given inequality?', 'Check \(y < 5x + 6\). At \(x = 3\), need \(y < 21\); at \(x = 5\), need \(y < 31\); at \(x = 7\), need \(y < 41\). Only the table \((3, 17), (5, 27), (7, 37)\) satisfies all: \(17 < 21\), \(27 < 31\), \(37 < 41\).', 'mc', '["\\((3, 17), (5, 27), (7, 37)\\)","\\((3, 17), (5, 35), (7, 37)\\)","\\((3, 25), (5, 35), (7, 45)\\)","\\((3, 21), (5, 31), (7, 41)\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M1 Q19'),
  ('lin-0034', 'linear-functions', '\(f(x) = 8x + 4\) The function \(f\) gives the estimated height, in feet, of a willow tree \(x\) years after its height was first measured. Which statement is the best interpretation of 4 in this context?', 'The constant term 4 is the value of \(f(0)\), the height at \(x = 0\), which is when the tree was first measured. So the tree was 4 feet tall when first measured.', 'mc', '["The tree will be measured each year for 4 years.","The tree is estimated to grow to a maximum height of 4 feet.","The estimated height of the tree increased by 4 feet each year.","The estimated height of the tree was 4 feet when it was first measured."]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q9'),
  ('lin-0035', 'linear-functions', 'Keenan made 32 cups of vegetable broth. Keenan then filled \(x\) small jars and \(y\) large jars with all the vegetable broth he made. The equation \(3x + 5y = 32\) represents this situation. Which is the best interpretation of \(5y\) in this context?', 'Each large jar holds 5 cups, and \(y\) is the number of large jars, so \(5y\) is the total number of cups of vegetable broth in the large jars.', 'mc', '["The number of large jars Keenan filled","The number of small jars Keenan filled","The total number of cups of vegetable broth in the large jars","The total number of cups of vegetable broth in the small jars"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q19'),
  ('lin-0036', 'linear-functions', 'For the linear function \(f\), the graph of \(y = f(x)\) in the \(xy\)-plane has a slope of 7 and passes through the point \((0, 5)\). Which equation defines \(f\)?', 'A line with slope 7 and \(y\)-intercept 5 (from the point \((0, 5)\)) is \(f(x) = 7x + 5\).', 'mc', '["\\(f(x) = 5x\\)","\\(f(x) = 35x\\)","\\(f(x) = 7x + 5\\)","\\(f(x) = 12x + 5\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P11M1 Q3'),
  ('lin-0037', 'linear-functions', 'Line \(k\) is defined by \(y = 6x + 4\). Line \(j\) is parallel to line \(k\) in the \(xy\)-plane and passes through the point \((0, 5)\). Which equation defines line \(j\)?', 'Parallel lines share the same slope, 6. Passing through \((0, 5)\) gives a \(y\)-intercept of 5, so \(y = 6x + 5\).', 'mc', '["\\(y = 6x + 5\\)","\\(y = -5x + 5\\)","\\(y = -6x + 5\\)","\\(y = 5x + 5\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M2 Q12'),
  ('lin-0038', 'linear-functions', 'A table shows four values of \(x\) and their corresponding values of \(g(x)\) for the linear function \(g\): when \(x = 1\), \(g(x) = 32\); when \(x = 2\), \(g(x) = 28\); when \(x = 3\), \(g(x) = 24\); when \(x = 4\), \(g(x) = 20\). The function can be written as \(g(x) = mx + b\), where \(m\) and \(b\) are constants. What is the value of \(b\)?', 'The slope is \(m = \frac{28 - 32}{2 - 1} = -4\). Using \((1, 32)\): \(32 = -4(1) + b\), so \(b = 36\).', 'mc', '["4","16","32","36"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M2 Q17'),
  ('sys-0001', 'systems-of-equations', '\(2.5b + 5r = 80\) The given equation describes the relationship between the number of birds, \(b\), and the number of reptiles, \(r\), that can be cared for at a pet care business on a given day. If the business cares for 16 reptiles on a given day, how many birds can it care for on this day?', 'Substitute \(r = 16\): \(2.5b + 5(16) = 80 \Rightarrow 2.5b + 80 = 80 \Rightarrow 2.5b = 0 \Rightarrow b = 0\).', 'mc', '["0","5","40","80"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M1 Q11'),
  ('sys-0002', 'systems-of-equations', '\(y = 2x^2 - 21x + 64\) \(y = 3x + a\) In the given system of equations, \(a\) is a constant. The graphs of the equations in the given system intersect at exactly one point, \((x, y)\), in the \(xy\)-plane. What is the value of \(x\)?', 'Setting equal: \(2x^2 - 21x + 64 = 3x + a\), so \(2x^2 - 24x + (64 - a) = 0\). For exactly one solution the discriminant is 0, giving \(x = \frac{24}{2 \cdot 2} = 6\) (the repeated root is \(-\frac{-24}{2\cdot 2} = 6\)).', 'mc', '["-8","-6","6","8"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M1 Q24'),
  ('sys-0003', 'systems-of-equations', '\(x + y = 18\) \(5y = x\) What is the solution \((x, y)\) to the given system of equations?', 'Substitute \(x = 5y\) into \(x + y = 18\): \(5y + y = 18 \Rightarrow 6y = 18 \Rightarrow y = 3\), so \(x = 15\). Solution: \((15, 3)\).', 'mc', '["\\((15, 3)\\)","\\((16, 2)\\)","\\((17, 1)\\)","\\((18, 0)\\)"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P4M2 Q4'),
  ('sys-0004', 'systems-of-equations', '\(s + 7r = 27\) \(r = 3\) What is the solution \((r, s)\) to the given system of equations?', 'Substitute \(r = 3\): \(s + 7(3) = 27 \Rightarrow s + 21 = 27 \Rightarrow s = 6\). The solution \((r, s)\) is \((3, 6)\).', 'mc', '["\\((6, 3)\\)","\\((3, 6)\\)","\\((3, 27)\\)","\\((27, 3)\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M1 Q4'),
  ('sys-0005', 'systems-of-equations', '\(y = 6x + 3\) One of the two equations in a system of linear equations is given. The system has infinitely many solutions. Which equation could be the second equation in this system?', 'For infinitely many solutions, the second equation must be equivalent to the first. \(2(y) = 2(6x + 3)\) simplifies to \(y = 6x + 3\), the same line.', 'mc', '["\\(y = 2(6x) + 3\\)","\\(y = 2(6x + 3)\\)","\\(2(y) = 2(6x) + 3\\)","\\(2(y) = 2(6x + 3)\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M1 Q12'),
  ('sys-0006', 'systems-of-equations', '\(3y = 4x + 17\) \(-3y = 9x - 23\) The solution to the given system of equations is \((x, y)\). What is the value of \(39x\)?', 'Adding the equations: \(0 = 13x - 6\), so \(x = \frac{6}{13}\). Then \(39x = 39 \cdot \frac{6}{13} = 3 \cdot 6 = 18\).', 'mc', '["-18","-6","6","18"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M2 Q18'),
  ('sys-0007', 'systems-of-equations', '\(y = -3x\) \(4x + y = 15\) The solution to the given system of equations is \((x, y)\). What is the value of \(x\)?', 'Substitute \(y = -3x\) into \(4x + y = 15\): \(4x - 3x = 15 \Rightarrow x = 15\).', 'mc', '["1","5","15","45"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q11'),
  ('sys-0008', 'systems-of-equations', '\(y = 6x + 18\) One of the equations in a system of two linear equations is given. The system has no solution. Which equation could be the second equation in the system?', 'The first equation is \(y = 6x + 18\), or \(-6x + y = 18\). A system has no solution when the lines are parallel (same slope, different intercept). \(-6x + y = 22\) has the same slope but a different constant, so the lines never meet.', 'mc', '["\\(-6x + y = 18\\)","\\(-6x + y = 22\\)","\\(-12x + y = 36\\)","\\(-12x + y = 18\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M2 Q23'),
  ('sys-0009', 'systems-of-equations', '\(2x + 3y = 7\) \(10x + 15y = 35\) For each real number \(r\), which of the following points lies on the graph of each equation in the \(xy\)-plane for the given system?', 'The two equations are equivalent (the second is 5 times the first), so every point on \(2x + 3y = 7\) satisfies both. Solving for \(x\): \(x = \frac{7 - 3y}{2}\). Letting \(y = r\) gives \(x = -\frac{3r}{2} + \frac{7}{2}\), i.e., the point \(\left(-\frac{3r}{2} + \frac{7}{2}, r\right)\).', 'mc', '["\\(\\left(\\frac{r}{5} + 7, -\\frac{r}{5} + 35\\right)\\)","\\(\\left(-\\frac{3r}{2} + \\frac{7}{2}, r\\right)\\)","\\(\\left(r, \\frac{2r}{3} + \\frac{7}{3}\\right)\\)","\\(\\left(r, -\\frac{3r}{2} + \\frac{7}{2}\\right)\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M2 Q25'),
  ('sys-0010', 'systems-of-equations', 'Jay walks at a speed of 3 miles per hour and runs at a speed of 5 miles per hour. He walks for \(w\) hours and runs for \(r\) hours for a combined total of 14 miles. Which equation represents this situation?', 'Distance equals speed times time. Walking distance is \(3w\) and running distance is \(5r\), totaling 14 miles: \(3w + 5r = 14\).', 'mc', '["\\(3w + 5r = 14\\)","\\(\\frac{1}{3}w + \\frac{1}{5}r = 14\\)","\\(\\frac{1}{3}w + \\frac{1}{5}r = 112\\)","\\(3w + 5r = 112\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q8'),
  ('sys-0011', 'systems-of-equations', '\(4x - 9y = 9y + 5\) \(hy = 2 + 4x\) In the given system of equations, \(h\) is a constant. If the system has no solution, what is the value of \(h\)?', 'Rewrite the first equation: \(4x - 18y = 5\), or \(4x = 18y + 5\). The second is \(4x = hy - 2\). For no solution, the lines must be parallel: the coefficients of \(y\) must match while constants differ, so \(h = 18\) (and \(-2 \ne 5\), confirming no solution).', 'mc', '["-9","0","9","18"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P9M1 Q19'),
  ('sys-0012', 'systems-of-equations', '\(3x = 12\) \(-3x + y = -6\) The solution to the given system of equations is \((x, y)\). What is the value of \(y\)?', 'From \(3x = 12\), \(x = 4\). Substitute into \(-3x + y = -6\): \(-12 + y = -6\), so \(y = 6\).', 'mc', '["-3","6","18","30"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M2 Q4'),
  ('sys-0013', 'systems-of-equations', '\(x + 5 = 14\) \(y = 4x^2 + 4\) At what point \((x, y)\) do the graphs of the equations in the given system intersect?', 'From \(x + 5 = 14\), \(x = 9\). Then \(y = 4(9)^2 + 4 = 4(81) + 4 = 324 + 4 = 328\), giving the point \((9, 328)\).', 'mc', '["\\((9, 324)\\)","\\((9, 328)\\)","\\((14, 4)\\)","\\((14, 788)\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P11M1 Q12'),
  ('sys-0014', 'systems-of-equations', '\(2x + 9y = 7\) The given equation is one equation in a system of two linear equations. If the system of equations has at least one solution, which of the following equations could be the other equation in the system? I. \(3x + 13.5y = 10.5\) II. \(3x - 13.5y = 10.5\)', 'Equation I is the first equation multiplied by 1.5, so it represents the same line (infinitely many solutions — at least one). Equation II has a different slope, so it intersects the first line at exactly one point (also at least one solution). Both work.', 'mc', '["I only","II only","I and II","Neither I nor II"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M1 Q25'),
  ('sys-0015', 'systems-of-equations', '\(10x = 110\) \(6x - 63 = y\) The solution to the given system of equations is \((x, y)\). What is the value of \(y\)?', 'From \(10x = 110\), \(x = 11\). Then \(y = 6(11) - 63 = 66 - 63 = 3\).', 'mc', '["63","11","10","3"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P11M2 Q4'),
  ('quad-0001', 'quadratics-polynomials', 'Square P has a side length of \(x\) inches. Square Q has a perimeter that is 176 inches greater than the perimeter of square P. The function \(f\) gives the area of square Q, in square inches. Which of the following defines \(f\)?', 'Perimeter of P is \(4x\), so perimeter of Q is \(4x + 176\), and side of Q is \(\frac{4x + 176}{4} = x + 44\). The area is \(f(x) = (x + 44)^2\).', 'mc', '["\\(f(x) = (x + 44)^2\\)","\\(f(x) = (x + 176)^2\\)","\\(f(x) = (176x + 44)^2\\)","\\(f(x) = (176x + 176)^2\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M1 Q18'),
  ('quad-0002', 'quadratics-polynomials', 'The expression \(4x^2 + bx - 45\), where \(b\) is a constant, can be rewritten as \((hx + k)(x + j)\), where \(h\), \(k\), and \(j\) are integer constants. Which of the following must be an integer?', 'Expanding \((hx + k)(x + j) = hx^2 + (hj + k)x + kj\). Matching constants: \(kj = -45\), so \(\frac{45}{k} = -j\), an integer. The other quotients need not be integers.', 'mc', '["\\(\\frac{b}{h}\\)","\\(\\frac{b}{k}\\)","\\(\\frac{45}{h}\\)","\\(\\frac{45}{k}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M1 Q23'),
  ('quad-0003', 'quadratics-polynomials', 'In the \(xy\)-plane, a parabola has vertex \((9, -14)\) and intersects the \(x\)-axis at two points. If the equation of the parabola is written in the form \(y = ax^2 + bx + c\), where \(a\), \(b\), and \(c\) are constants, which of the following could be the value of \(a + b + c\)?', 'In vertex form \(y = a(x - 9)^2 - 14\). Then \(a + b + c = y(1) = a(1-9)^2 - 14 = 64a - 14\). Since the parabola opens upward to cross the x-axis twice from vertex below the axis, \(a > 0\), making \(64a - 14 > -14\). Only \(-12\) exceeds \(-14\) and gives \(a = \frac{2}{64} > 0\).', 'mc', '["-23","-19","-14","-12"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M1 Q26'),
  ('quad-0004', 'quadratics-polynomials', '\(-4x^2 - 7x = -36\) What is the positive solution to the given equation?', 'Rewrite as \(4x^2 + 7x - 36 = 0\). Factoring: \((4x - 9)(x + 4) = 0\), giving \(x = \frac{9}{4}\) or \(x = -4\). The positive solution is \(\frac{9}{4}\).', 'mc', '["\\(\\frac{7}{4}\\)","\\(\\frac{9}{4}\\)","4","7"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M2 Q12'),
  ('quad-0005', 'quadratics-polynomials', '\(f(x) = (x - 10)(x + 13)\) The function \(f\) is defined by the given equation. For what value of \(x\) does \(f(x)\) reach its minimum?', 'The zeros are \(x = 10\) and \(x = -13\). The vertex (minimum, since parabola opens up) is at the midpoint: \(x = \frac{10 + (-13)}{2} = -\frac{3}{2}\).', 'mc', '["-130","-13","\\(-\\frac{23}{2}\\)","\\(-\\frac{3}{2}\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P4M2 Q18'),
  ('quad-0006', 'quadratics-polynomials', 'The function \(f(x) = \frac{1}{9}(x - 7)^2 + 3\) gives a metal ball''s height above the ground \(f(x)\), in inches, \(x\) seconds after it started moving on a track, where \(0 \le x \le 10\). Which of the following is the best interpretation of the vertex of the graph of \(y = f(x)\) in the \(xy\)-plane?', 'The vertex is at \((7, 3)\). Since the coefficient \(\frac{1}{9}\) is positive, the vertex is a minimum, so the ball''s minimum height was 3 inches above the ground.', 'mc', '["The metal ball''s minimum height was 3 inches above the ground.","The metal ball''s minimum height was 7 inches above the ground.","The metal ball''s height was 3 inches above the ground when it started moving.","The metal ball''s height was 7 inches above the ground when it started moving."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M2 Q19'),
  ('quad-0007', 'quadratics-polynomials', 'A right rectangular prism has a height of 9 inches. The length of the prism''s base is \(x\) inches, which is 7 inches more than the width of the prism''s base. Which function \(V\) gives the volume of the prism, in cubic inches, in terms of the length of the prism''s base?', 'The length is \(x\), the width is \(x - 7\), and the height is 9. Volume \(= \text{length} \times \text{width} \times \text{height} = 9x(x - 7)\).', 'mc', '["\\(V(x) = x(x + 9)(x + 7)\\)","\\(V(x) = x(x + 9)(x - 7)\\)","\\(V(x) = 9x(x + 7)\\)","\\(V(x) = 9x(x - 7)\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q23'),
  ('quad-0008', 'quadratics-polynomials', 'The function \(f\) is defined by \(f(x) = ax^2 + bx + c\), where \(a\), \(b\), and \(c\) are constants. The graph of \(y = f(x)\) in the \(xy\)-plane passes through the points \((7, 0)\) and \((-3, 0)\). If \(a\) is an integer greater than 1, which of the following could be the value of \(a + b\)?', 'With roots 7 and \(-3\), \(f(x) = a(x - 7)(x + 3) = a(x^2 - 4x - 21)\), so \(b = -4a\) and \(a + b = a - 4a = -3a\). For integer \(a > 1\): \(a = 2\) gives \(-6\). So \(-6\) is possible.', 'mc', '["-6","-3","4","5"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M1 Q26'),
  ('quad-0009', 'quadratics-polynomials', 'Which expression is equivalent to \(16x^3 y^2 + 14xy\)?', 'The greatest common factor of \(16x^3 y^2\) and \(14xy\) is \(2xy\). Factoring: \(2xy(8x^2 y + 7)\), since \(2xy \cdot 8x^2 y = 16x^3 y^2\) and \(2xy \cdot 7 = 14xy\).', 'mc', '["\\(2xy(8xy + 7)\\)","\\(2xy(8x^2 y + 7)\\)","\\(14xy(2x^2 y + 1)\\)","\\(14xy(8x^2 y + 1)\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q4'),
  ('quad-0010', 'quadratics-polynomials', 'The kinetic energy, in joules, of an object with mass 9 kilograms traveling at a speed of \(v\) meters per second is given by the function \(K\), where \(K(v) = \frac{9}{2}v^2\). Which of the following is the best interpretation of \(K(34) = 5{,}202\) in this context?', 'In \(K(v)\), the input \(v = 34\) is the speed and the output 5,202 is the kinetic energy, so an object at 34 meters per second has 5,202 joules of kinetic energy.', 'mc', '["The object traveling at 34 meters per second has a kinetic energy of 5,202 joules.","The object traveling at 340 meters per second has a kinetic energy of 5,202 joules.","The object traveling at 5,202 meters per second has a kinetic energy of 34 joules.","The object traveling at 23,409 meters per second has a kinetic energy of 34 joules."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q10'),
  ('quad-0011', 'quadratics-polynomials', 'Which expression is equivalent to \((8x^3 + 8) - (x^3 - 2)\)?', 'Distribute the subtraction: \(8x^3 + 8 - x^3 + 2 = 7x^3 + 10\).', 'mc', '["\\(8x^3 + 6\\)","\\(7x^3 + 10\\)","\\(8x^3 + 10\\)","\\(7x^3 + 6\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P5M2 Q17'),
  ('quad-0012', 'quadratics-polynomials', 'Which quadratic equation has no real solutions?', 'A quadratic has no real solutions when its discriminant \(b^2 - 4ac < 0\). For \(5x^2 - 14x + 49\): \((-14)^2 - 4(5)(49) = 196 - 980 = -784 < 0\), so it has no real solutions.', 'mc', '["\\(x^2 + 14x - 49 = 0\\)","\\(x^2 - 14x + 49 = 0\\)","\\(5x^2 - 14x - 49 = 0\\)","\\(5x^2 - 14x + 49 = 0\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M2 Q24'),
  ('quad-0013', 'quadratics-polynomials', '\(k^2 - 53 = 91\) What is the positive solution to the given equation?', '\(k^2 = 91 + 53 = 144\), so \(k = \sqrt{144} = 12\) (positive solution).', 'mc', '["144","72","38","12"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P6M1 Q3'),
  ('quad-0014', 'quadratics-polynomials', 'Which expression is equivalent to \((x^2 + 11)^2 + (x - 5)(x + 5)\)?', '\((x^2 + 11)^2 = x^4 + 22x^2 + 121\) and \((x-5)(x+5) = x^2 - 25\). Sum: \(x^4 + 23x^2 + 96\).', 'mc', '["\\(x^4 + 23x^2 - 14\\)","\\(x^4 + 23x^2 + 96\\)","\\(x^4 + 12x^2 + 121\\)","\\(x^4 + x^2 + 146\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q12'),
  ('quad-0015', 'quadratics-polynomials', '\(w^2 + 12w - 40 = 0\) Which of the following is a solution to the given equation?', 'Using the quadratic formula: \(w = \frac{-12 \pm \sqrt{144 + 160}}{2} = \frac{-12 \pm \sqrt{304}}{2} = -6 \pm 2\sqrt{19}\). One solution is \(-6 + 2\sqrt{19}\).', 'mc', '["\\(6 - 2\\sqrt{19}\\)","\\(2\\sqrt{19}\\)","\\(\\sqrt{19}\\)","\\(-6 + 2\\sqrt{19}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M1 Q18'),
  ('quad-0016', 'quadratics-polynomials', 'Which expression is equivalent to \(5x^5 - 6x^4 + 8x^3\)?', 'The greatest common factor of the three terms is \(x^3\). Factoring: \(x^3(5x^2 - 6x + 8)\).', 'mc', '["\\(x^4(5x - 6)\\)","\\(x^3(5x^2 - 6x + 8)\\)","\\(8x^3(5x^2 - 6x + 1)\\)","\\(6x^5(-6x^4 + 8x^3 + 1)\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q8'),
  ('quad-0017', 'quadratics-polynomials', '\((x + 2)(x - 5)(x + 9) = 0\) What is a positive solution to the given equation?', 'Setting each factor to zero gives \(x = -2, 5, -9\). The positive solution is 5.', 'mc', '["3","4","5","18"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q12'),
  ('quad-0018', 'quadratics-polynomials', '\(x^2 = -841\) How many distinct real solutions does the given equation have?', 'A squared real number cannot be negative, so \(x^2 = -841\) has no real solutions: zero.', 'mc', '["Exactly one","Exactly two","Infinitely many","Zero"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q17'),
  ('quad-0019', 'quadratics-polynomials', 'Which expression is equivalent to \(23x^3 + 2x^2 + 9x\)?', 'The greatest common factor is \(x\). Factoring: \(x(23x^2 + 2x + 9)\).', 'mc', '["\\(23x(x^2 + 2x + 9)\\)","\\(9x(23x^3 + 2x^2 + 1)\\)","\\(x(23x^2 + 2x + 9)\\)","\\(34(x^3 + x^2 + x)\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M2 Q9'),
  ('quad-0020', 'quadratics-polynomials', 'Which expression is equivalent to \((9x^3 + 5x + 7) + (6x^3 + 5x^2 - 5)\)?', 'Combine like terms: \((9x^3 + 6x^3) + 5x^2 + 5x + (7 - 5) = 15x^3 + 5x^2 + 5x + 2\).', 'mc', '["\\(15x^6 + 5x^2 - 5x - 35\\)","\\(15x^3 + 10x^2 + 2\\)","\\(15x^6 + 5x^2 + 5x + 2\\)","\\(15x^3 + 5x^2 + 5x + 2\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M2 Q10'),
  ('quad-0021', 'quadratics-polynomials', '\(h(t) = -16t^2 + b\) The function \(h\) estimates an object''s height, in feet, above the ground \(t\) seconds after the object is dropped, where \(b\) is a constant. The function estimates that the object is 3,364 feet above the ground when it is dropped at \(t = 0\). Approximately how many seconds after being dropped does the function estimate the object will hit the ground?', 'At \(t = 0\), \(h = b = 3{,}364\). The object hits the ground when \(h = 0\): \(-16t^2 + 3{,}364 = 0 \Rightarrow t^2 = 210.25 \Rightarrow t = 14.5\) seconds.', 'mc', '["7.25","14.50","105.13","210.25"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M2 Q19'),
  ('quad-0022', 'quadratics-polynomials', '\(x - 29 = (x - a)(x - 29)\) Which of the following are solutions to the given equation, where \(a\) is a constant and \(a > 30\)? I. \(a\) II. \(a + 1\) III. \(29\)', 'Rewrite as \((x - 29) - (x - a)(x - 29) = 0\), so \((x - 29)[1 - (x - a)] = 0\), giving \((x - 29)(a + 1 - x) = 0\). Solutions are \(x = 29\) (III) and \(x = a + 1\) (II). So II and III only.', 'mc', '["I and II only","I and III only","II and III only","I, II, and III"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M1 Q24'),
  ('quad-0023', 'quadratics-polynomials', 'In the \(xy\)-plane, the graph of the equation \(y = -x^2 + 9x - 100\) intersects the line \(y = c\) at exactly one point. What is the value of \(c\)?', 'The line \(y = c\) touches the parabola at exactly one point when \(c\) equals the maximum value at the vertex. The vertex \(x\)-value is \(\frac{-9}{2(-1)} = \frac{9}{2}\), and \(y = -\left(\frac{9}{2}\right)^2 + 9\left(\frac{9}{2}\right) - 100 = -\frac{81}{4} + \frac{81}{2} - 100 = \frac{81}{4} - 100 = -\frac{319}{4}\).', 'mc', '["\\(-\\frac{481}{4}\\)","\\(-100\\)","\\(-\\frac{319}{4}\\)","\\(-\\frac{9}{2}\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M1 Q25'),
  ('quad-0024', 'quadratics-polynomials', 'The function \(f\) is defined by \(f(x) = 7x^3\). In the \(xy\)-plane, the graph of \(y = g(x)\) is the result of shifting the graph of \(y = f(x)\) down 2 units. Which equation defines function \(g\)?', 'Shifting down 2 units subtracts 2 from the output: \(g(x) = 7x^3 - 2\).', 'mc', '["\\(g(x) = \\frac{7}{2}x^3\\)","\\(g(x) = 7x^{\\frac{3}{2}}\\)","\\(g(x) = 7x^3 + 2\\)","\\(g(x) = 7x^3 - 2\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q10'),
  ('quad-0025', 'quadratics-polynomials', '\(\frac{x^2}{\sqrt{x^2 - c^2}} = \frac{c^2}{\sqrt{x^2 - c^2}} + 39\) In the given equation, \(c\) is a positive constant. Which of the following is one of the solutions to the given equation?', 'Multiply through: \(\frac{x^2 - c^2}{\sqrt{x^2 - c^2}} = 39\), so \(\sqrt{x^2 - c^2} = 39\). Squaring gives \(x^2 - c^2 = 39^2\), so \(x^2 = c^2 + 39^2\) and \(x = \pm\sqrt{c^2 + 39^2}\). One solution is \(-\sqrt{c^2 + 39^2}\).', 'mc', '["\\(-c\\)","\\(-c^2 - 39^2\\)","\\(-\\sqrt{39^2 - c^2}\\)","\\(-\\sqrt{c^2 + 39^2}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M2 Q26'),
  ('quad-0026', 'quadratics-polynomials', 'The function \(g\) is defined by \(g(x) = x^2 + 9\). For which value of \(x\) is \(g(x) = 25\)?', 'Set \(x^2 + 9 = 25\), so \(x^2 = 16\) and \(x = 4\) (a valid choice).', 'mc', '["4","5","9","13"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P9M1 Q4'),
  ('quad-0027', 'quadratics-polynomials', 'Function \(f\) is defined by \(f(x) = (x + 6)(x + 5)(x + 1)\). Function \(g\) is defined by \(g(x) = f(x - 1)\). The graph of \(y = g(x)\) in the \(xy\)-plane has \(x\)-intercepts at \((a, 0)\), \((b, 0)\), and \((c, 0)\), where \(a\), \(b\), and \(c\) are distinct constants. What is the value of \(a + b + c\)?', 'The roots of \(f\) are \(-6, -5, -1\). Since \(g(x) = f(x - 1)\), the graph shifts right 1 unit, so the roots become \(-5, -4, 0\). Their sum is \(-5 + (-4) + 0 = -9\).', 'mc', '["-15","-9","11","15"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M1 Q22'),
  ('quad-0028', 'quadratics-polynomials', '\(f(x) = 4x^2 + 64x + 262\) The function \(g\) is defined by \(g(x) = f(x + 5)\). For what value of \(x\) does \(g(x)\) reach its minimum?', 'The minimum of \(f\) is at \(x = \frac{-64}{2(4)} = -8\). Since \(g(x) = f(x + 5)\), the graph shifts left 5 units, so its minimum is at \(x = -8 - 5 = -13\).', 'mc', '["-13","-8","-5","-3"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P9M1 Q24'),
  ('quad-0029', 'quadratics-polynomials', '\(x + 7 = 10\) \((x + 7)^2 = y\) Which ordered pair \((x, y)\) is a solution to the given system of equations?', 'From \(x + 7 = 10\), \(x = 3\). Then \(y = (x + 7)^2 = 10^2 = 100\), giving \((3, 100)\).', 'mc', '["\\((3, 100)\\)","\\((3, 3)\\)","\\((3, 10)\\)","\\((3, 70)\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q9'),
  ('quad-0030', 'quadratics-polynomials', '\(y = 76\) \(y = x^2 - 5\) The graphs of the given equations in the \(xy\)-plane intersect at the point \((x, y)\). What is a possible value of \(x\)?', 'Set \(x^2 - 5 = 76\), so \(x^2 = 81\) and \(x = \pm 9\). A possible value is \(-9\).', 'mc', '["\\(-\\frac{76}{5}\\)","-9","5","76"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q10'),
  ('quad-0031', 'quadratics-polynomials', '\(|-5x + 13| = 73\) What is the sum of the solutions to the given equation?', 'The two cases are \(-5x + 13 = 73\), giving \(x = -12\), and \(-5x + 13 = -73\), giving \(x = \frac{86}{5}\). Their sum is \(-12 + \frac{86}{5} = \frac{-60 + 86}{5} = \frac{26}{5}\).', 'mc', '["\\(-\\frac{146}{5}\\)","-12","0","\\(\\frac{26}{5}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M2 Q22'),
  ('quad-0032', 'quadratics-polynomials', '\(-9x^2 + 30x + c = 0\) In the given equation, \(c\) is a constant. The equation has exactly one solution. What is the value of \(c\)?', 'A quadratic has exactly one solution when its discriminant is 0: \(30^2 - 4(-9)(c) = 900 + 36c = 0\), so \(c = -25\).', 'mc', '["3","0","-25","-53"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M2 Q24'),
  ('quad-0033', 'quadratics-polynomials', 'Which of the following expressions has a factor of \(x + 2b\), where \(b\) is a positive integer constant?', 'If \(x + 2b\) is a factor, then \(3x^2 + Bx + 14b = (x + 2b)(3x + 7)\) for the constant term to match (\(2b \cdot 7 = 14b\)). Expanding: \((x + 2b)(3x + 7) = 3x^2 + (7 + 6b)x + 14b\). Matching the middle coefficient to \(49\): \(7 + 6b = 49 \Rightarrow b = 7\), an integer. So \(3x^2 + 49x + 14b\) has the factor.', 'mc', '["\\(3x^2 + 7x + 14b\\)","\\(3x^2 + 28x + 14b\\)","\\(3x^2 + 42x + 14b\\)","\\(3x^2 + 49x + 14b\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M2 Q25'),
  ('quad-0034', 'quadratics-polynomials', '\(8x^2 - 40 = 32\) What is the positive solution to the given equation?', 'Add 40 to both sides: \(8x^2 = 72\), so \(x^2 = 9\) and the positive solution is \(x = 3\).', 'mc', '["3","4","9","72"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P11M1 Q4'),
  ('quad-0035', 'quadratics-polynomials', 'Which quadratic equation has exactly one distinct real solution?', '\((x + 15)^2 = 0\) gives the single repeated solution \(x = -15\). A negative right side (option B) has no real solution, and a positive right side (options C and D) yields two distinct solutions.', 'mc', '["\\((x + 15)^2 = 0\\)","\\((x + 15)^2 = -45\\)","\\((x + 15)^2 = 45\\)","\\((x + 15)^2 = 135\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q16'),
  ('quad-0036', 'quadratics-polynomials', 'A table shows three values of \(x\) and their corresponding values of \(f(x)\) for the quadratic function \(f\): when \(x = 24\), \(f(x) = -8\); when \(x = 30\), \(f(x) = -8\); when \(x = 32\), \(f(x) = 8\). Which equation defines \(f\)?', 'Since \(f(24) = f(30) = -8\), test \(f(x) = (x - 24)(x - 30) - 8\): at \(x = 24\) and \(x = 30\) the product is 0, giving \(-8\); at \(x = 32\), \((8)(2) - 8 = 16 - 8 = 8\). All three values match.', 'mc', '["\\(f(x) = (x - 24)(x - 30) + 4\\)","\\(f(x) = (x - 24)(x - 30) - 8\\)","\\(f(x) = (x - 8)(x - 32) + 32\\)","\\(f(x) = (x - 8)(x - 32) - 32\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M2 Q18'),
  ('quad-0037', 'quadratics-polynomials', '\(f(x) = -6x^2 + 60x - 126\) The function \(f\) is defined by the given equation. Which of the following equivalent forms of the equation displays the maximum value of the function as a constant or coefficient?', 'The vertex form \(f(x) = -6(x - 5)^2 + 24\) shows the maximum value 24 as a constant (the parabola opens downward, so the vertex is a maximum).', 'mc', '["\\(f(x) = -6x^2 + 42x + 18x - 126\\)","\\(f(x) = -6x(x - 7) + 18(x - 7)\\)","\\(f(x) = -6(x - 5)^2 + 24\\)","\\(f(x) = -6(x - 7)(x - 3)\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M2 Q22'),
  ('quad-0038', 'quadratics-polynomials', '\(52(x^3 + 64)(x^4 - 81) = 0\) How many distinct real solutions does the given equation have?', 'The factor \(x^3 + 64 = 0\) gives one real solution, \(x = -4\). The factor \(x^4 - 81 = 0\) gives \(x^4 = 81\), with two real solutions \(x = 3\) and \(x = -3\) (the other two roots are non-real). In total there are 3 distinct real solutions.', 'mc', '["Exactly two","Exactly three","Exactly five","Exactly seven"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M2 Q24'),
  ('exp-0001', 'exponential-functions', 'The function \(f(x) = 206(1.034)^x\) models the value, in dollars, of a certain bank account by the end of each year from 1957 through 1972, where \(x\) is the number of years after 1957. Which of the following is the best interpretation of "\(f(5)\) is approximately equal to 243" in this context?', '\(x = 5\) corresponds to 5 years after 1957, which is 1962, and \(f(5) \approx 243\) means the account value is about 243 dollars in 1962.', 'mc', '["The value of the bank account is estimated to be approximately 5 dollars greater in 1962 than in 1957.","The value of the bank account is estimated to be approximately 243 dollars in 1962.","The value, in dollars, of the bank account is estimated to be approximately 5 times greater in 1962 than in 1957.","The value of the bank account is estimated to increase by approximately 243 dollars every 5 years between 1957 and 1972."]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M1 Q16'),
  ('exp-0002', 'exponential-functions', 'The function \(f\) is defined by \(f(x) = 270(0.1)^x\). What is the value of \(f(0)\)?', '\(f(0) = 270(0.1)^0 = 270(1) = 270\).', 'mc', '["0","1","27","270"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P4M2 Q9'),
  ('exp-0003', 'exponential-functions', '\(f(x) = 5{,}470(0.64)^{\frac{x}{12}}\) The function \(f\) gives the value, in dollars, of a certain piece of equipment after \(x\) months of use. If the value of the equipment decreases each year by \(p\%\) of its value the preceding year, what is the value of \(p\)?', 'Over one year (12 months), the factor is \((0.64)^{\frac{12}{12}} = 0.64\), so the value is 64% of the previous year, a decrease of \(100 - 64 = 36\%\). Thus \(p = 36\).', 'mc', '["4","5","36","64"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M2 Q23'),
  ('exp-0004', 'exponential-functions', 'Which of the following functions has(have) a minimum value at \(-3\)? I. \(f(x) = -6(3)^x - 3\) II. \(g(x) = -3(6)^x\)', 'Both functions have a negative leading coefficient multiplying a growing exponential, so each decreases without bound (no minimum). Function I approaches \(-3\) as an asymptote from below but never reaches a minimum; function II approaches 0 from below. Neither attains a minimum value of \(-3\).', 'mc', '["I only","II only","I and II","Neither I nor II"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M1 Q24'),
  ('exp-0005', 'exponential-functions', '\(P(t) = 260(1.04)^{\left(\frac{6}{4}\right)t}\) The function \(P\) models the population, in thousands, of a certain city \(t\) years after 2003. According to the model, the population is predicted to increase by 4% every \(n\) months. What is the value of \(n\)?', 'The base 1.04 (a 4% increase) applies when the exponent \(\frac{6}{4}t = 1\), i.e. \(t = \frac{4}{6} = \frac{2}{3}\) years. Converting to months: \(\frac{2}{3} \times 12 = 8\) months.', 'mc', '["8","12","18","72"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M2 Q25'),
  ('exp-0006', 'exponential-functions', '\(P(t) = 1{,}800(1.02)^t\) The function \(P\) gives the estimated number of marine mammals in a certain area, where \(t\) is the number of years since a study began. What is the best interpretation of \(P(0) = 1{,}800\) in this context?', 'At \(t = 0\) (when the study began), \(P(0) = 1{,}800\), so there were an estimated 1,800 marine mammals at the start.', 'mc', '["The estimated number of marine mammals in the area was 102 when the study began.","The estimated number of marine mammals in the area was 1,800 when the study began.","The estimated number of marine mammals in the area increased by 102 each year during the study.","The estimated number of marine mammals in the area increased by 1,800 each year during the study."]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q9'),
  ('exp-0007', 'exponential-functions', 'At the time that an article was first featured on the home page of a news website, there were 40 comments on the article. An exponential model estimates that at the end of each hour after the article was first featured on the home page, the number of comments on the article had increased by 190% of the number of comments on the article at the end of the previous hour. Which of the following equations best represents this model, where \(C\) is the estimated number of comments on the article \(t\) hours after the article was first featured on the home page and \(t \le 4\)?', 'An increase of 190% each hour means the new amount is the previous amount plus 1.9 times it, a factor of \(1 + 1.9 = 2.9\). So \(C = 40(2.9)^t\).', 'mc', '["\\(C = 40(1.19)^t\\)","\\(C = 40(1.9)^t\\)","\\(C = 40(19)^t\\)","\\(C = 40(2.9)^t\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M1 Q25'),
  ('exp-0008', 'exponential-functions', '\(f(x) = (1.84)^{\frac{x}{4}}\) The function \(f\) is defined by the given equation. The equation can be rewritten as \(f(x) = \left(1 + \frac{p}{100}\right)^x\), where \(p\) is a constant. Which of the following is closest to the value of \(p\)?', 'Rewrite \((1.84)^{x/4} = \left((1.84)^{1/4}\right)^x\). Now \((1.84)^{1/4} \approx 1.1646\), so \(1 + \frac{p}{100} \approx 1.1646\), giving \(p \approx 16\).', 'mc', '["16","21","46","96"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M2 Q23'),
  ('exp-0009', 'exponential-functions', 'For the exponential function \(f\), the value of \(f(0)\) is \(c\), where \(c\) is a constant. Of the following equations that define the function \(f\), which equation shows the value of \(c\) as the coefficient or the base?', '\(f(0) = c\). For \(f(x) = 33(1.5)^x\), \(f(0) = 33\), so \(c = 33\) appears directly as the coefficient.', 'mc', '["\\(f(x) = 22(1.5)^{x+1}\\)","\\(f(x) = 33(1.5)^x\\)","\\(f(x) = 49.5(1.5)^{x-1}\\)","\\(f(x) = 74.25(1.5)^{x-2}\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M1 Q17'),
  ('exp-0010', 'exponential-functions', 'The function \(f(t) = 40{,}000(2)^{\frac{t}{790}}\) gives the number of bacteria in a population \(t\) minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?', 'The population doubles when the exponent \(\frac{t}{790} = 1\), i.e. \(t = 790\) minutes.', 'mc', '["2","790","1,580","40,000"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M1 Q18'),
  ('exp-0011', 'exponential-functions', 'Which expression is equivalent to \(\frac{h^{15}q^7}{h^5 q^{21}}\), where \(h > 0\) and \(q > 0\)?', 'Subtract exponents for like bases: \(h^{15-5} = h^{10}\) and \(q^{7-21} = q^{-14}\). So the expression is \(\frac{h^{10}}{q^{14}}\).', 'mc', '["\\(\\frac{h^{10}}{q^{14}}\\)","\\(\\frac{h^3}{q^3}\\)","\\(h^{10}q^{14}\\)","\\(h^3 q^3\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M2 Q17'),
  ('exp-0012', 'exponential-functions', 'The graph shown is an increasing exponential curve that approaches the \(x\)-axis on the left and crosses the \(y\)-axis at 8. What is the \(y\)-intercept of the graph shown?', 'The \(y\)-intercept is where the curve crosses the \(y\)-axis, which occurs at \((0, 8)\).', 'mc', '["\\((-8, 0)\\)","\\((-6, 0)\\)","\\((0, 6)\\)","\\((0, 8)\\)"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M1 Q3'),
  ('exp-0013', 'exponential-functions', 'A model predicts that the population of Bergen was 15,000 in 2005. The model also predicts that each year for the next 5 years, the population \(p\) increased by 4% of the previous year''s population. Which equation best represents this model, where \(x\) is the number of years after 2005, for \(x \le 5\)?', 'A 4% annual increase gives a growth factor of \(1.04\), starting from 15,000: \(p = 15{,}000(1.04)^x\).', 'mc', '["\\(p = 0.96(15{,}000)^x\\)","\\(p = 1.04(15{,}000)^x\\)","\\(p = 15{,}000(0.96)^x\\)","\\(p = 15{,}000(1.04)^x\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q12'),
  ('exp-0014', 'exponential-functions', 'The functions \(f\) and \(g\) are defined by the given equations, where \(x \ge 0\). Which of the following equations displays, as a constant or coefficient, the maximum value of the function it defines, where \(x \ge 0\)? I. \(f(x) = 18(1.25)^x + 41\) II. \(g(x) = 9(0.73)^x\)', 'For \(g(x) = 9(0.73)^x\) with base less than 1, the function decreases, so its maximum at \(x = 0\) is \(9\), which appears as the coefficient. For \(f(x) = 18(1.25)^x + 41\), the base exceeds 1, so the function increases without bound and has no maximum. Only II displays its maximum.', 'mc', '["I only","II only","I and II","Neither I nor II"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M1 Q26'),
  ('exp-0015', 'exponential-functions', 'Which expression is equivalent to \(a^{\frac{11}{12}}\), where \(a > 0\)?', '\(\sqrt[144]{a^{132}} = a^{\frac{132}{144}} = a^{\frac{11}{12}}\).', 'mc', '["\\(\\sqrt[12]{a^{132}}\\)","\\(\\sqrt[144]{a^{132}}\\)","\\(\\sqrt[121]{a^{132}}\\)","\\(\\sqrt[11]{a^{132}}\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P8M2 Q18'),
  ('exp-0016', 'exponential-functions', 'A company opens an account with an initial balance of 36,100.00 dollars. The account earns interest, and no additional deposits or withdrawals are made. The account balance is given by an exponential function \(A\), where \(A(t)\) is the account balance, in dollars, \(t\) years after the account is opened. The account balance after 13 years is 68,071.93 dollars. Which equation could define \(A\)?', 'The initial balance at \(t = 0\) must be 36,100.00, which rules out the options starting at 31,971.93. A growth factor of 1.05 gives \(36{,}100(1.05)^{13} \approx 68{,}072\), matching the given balance, so \(A(t) = 36{,}100.00(1.05)^t\).', 'mc', '["\\(A(t) = 36{,}100.00(1.05)^t\\)","\\(A(t) = 31{,}971.93(1.05)^t\\)","\\(A(t) = 31{,}971.93(0.05)^t\\)","\\(A(t) = 36{,}100.00(0.05)^t\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q11'),
  ('exp-0017', 'exponential-functions', 'For \(x > 0\), the function \(f\) is defined as follows: \(f(x)\) equals 201% of \(x\). Which of the following could describe this function?', '\(f(x) = 2.01x\) is a linear function with positive slope, so it is increasing linear.', 'mc', '["Decreasing exponential","Decreasing linear","Increasing exponential","Increasing linear"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P9M1 Q23'),
  ('exp-0018', 'exponential-functions', 'Rosa opened a savings account at a bank. A table shows the exponential relationship between the time \(t\), in years, since Rosa opened the account and the total amount \(n\), in dollars, in the account: at \(t = 0\), \(n = 604.00\); at \(t = 1\), \(n = 606.42\); at \(t = 2\), \(n = 608.84\). If Rosa made no additional deposits or withdrawals, which of the following equations best represents the relationship between \(t\) and \(n\)?', 'The initial amount at \(t = 0\) is 604. The yearly growth factor is \(\frac{606.42}{604} \approx 1.004\), a 0.4% increase. So \(n = 604(1 + 0.004)^t\).', 'mc', '["\\(n = (1 + 604)^t\\)","\\(n = (1 + 0.004)^t\\)","\\(n = 604(1 + 0.004)^t\\)","\\(n = 0.004(1 + 604)^t\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M2 Q11'),
  ('exp-0019', 'exponential-functions', 'The population of Greenville increased by 7% from 2015 to 2016. If the 2016 population is \(k\) times the 2015 population, what is the value of \(k\)?', 'A 7% increase multiplies the population by \(1 + 0.07 = 1.07\), so \(k = 1.07\).', 'mc', '["0.07","0.7","1.07","1.7"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q16'),
  ('exp-0020', 'exponential-functions', '\(m(t) = -0.0274\left(\frac{t}{7}\right)^2 + 7.3873\left(\frac{t}{7}\right) + 75.032\) The function \(m\) gives the predicted body mass \(m(t)\), in kilograms (kg), of a certain animal \(t\) days after it was born in a wildlife reserve, where \(t \le 390\). Which of the following is the best interpretation of the statement "\(m(330)\) is approximately equal to 362" in this context?', 'In \(m(t)\), the input \(t\) is days and the output is body mass in kg. So \(m(330) \approx 362\) means the predicted body mass was about 362 kg when the animal was 330 days old.', 'mc', '["The predicted body mass of the animal was approximately 330 kg 362 days after it was born.","The predicted body mass of the animal was approximately 362 kg 330 days after it was born.","The predicted body mass of the animal was approximately 362 times 330 divided by 7 days after it was born.","The predicted body mass of the animal was approximately 330 divided by 7 kg 362 days after it was born."]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M2 Q18'),
  ('exp-0021', 'exponential-functions', 'The function \(f\) is defined by \(f(x) = a(2.2^x + 2.2^b)\), where \(a\) and \(b\) are integer constants and \(0 < a < b\). The functions \(g\) and \(h\) are equivalent to function \(f\), where \(k\) and \(m\) are constants. Which of the following equations displays the \(y\)-coordinate of the \(y\)-intercept of the graph of \(y = f(x)\) in the \(xy\)-plane as a constant or coefficient? I. \(g(x) = a(2.2^x + k)\) II. \(h(x) = a(2.2)^x + m\)', 'The \(y\)-intercept is \(f(0) = a(2.2^0 + 2.2^b) = a(1 + 2.2^b)\). In form I, \(g(x) = a(2.2^x + k)\) has \(g(0) = a(1 + k)\), so the intercept value \(a(1+k)\) is not shown as a standalone constant. In form II, \(h(x) = a(2.2)^x + m\) has \(h(0) = a + m\), which also does not display the full intercept as a single constant. Neither displays it directly.', 'mc', '["I only","II only","I and II","Neither I nor II"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M2 Q26'),
  ('exp-0022', 'exponential-functions', 'Which expression is equivalent to \((m^4 q^4 z^{-1})(m q^5 z^3)\), where \(m\), \(q\), and \(z\) are positive?', 'Add exponents of like bases: \(m^{4+1} q^{4+5} z^{-1+3} = m^5 q^9 z^2\).', 'mc', '["\\(m^4 q^{20} z^{-3}\\)","\\(m^5 q^9 z^2\\)","\\(m^6 q^8 z^{-1}\\)","\\(m^{20} q^{12} z^{-2}\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q11'),
  ('exp-0023', 'exponential-functions', 'An airplane descends from an altitude of 9,500 feet to 5,000 feet at a constant rate of 400 feet per minute. What type of function best models the relationship between the descending airplane''s altitude and time?', 'A constant rate of descent means altitude decreases by a fixed amount each minute, which is a decreasing linear function.', 'mc', '["Decreasing exponential","Decreasing linear","Increasing exponential","Increasing linear"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q12'),
  ('exp-0024', 'exponential-functions', 'The number of bacteria in a liquid medium doubles every day. There are 44,000 bacteria in the liquid medium at the start of an observation. Which of the following represents the number of bacteria, \(y\), in the liquid medium \(t\) days after the start of the observation?', 'Starting at 44,000 and doubling each day gives a growth factor of 2: \(y = 44{,}000(2)^t\).', 'mc', '["\\(y = \\frac{1}{2}(44{,}000)^t\\)","\\(y = 2(44{,}000)^t\\)","\\(y = 44{,}000\\left(\\frac{1}{2}\\right)^t\\)","\\(y = 44{,}000(2)^t\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q16'),
  ('exp-0025', 'exponential-functions', 'A table shows the exponential relationship between the number of years, \(x\), since Hana started training in pole vault, and the estimated height \(h(x)\), in meters, of her best pole vault for that year: at \(x = 0\), \(h(x) = 1.23\); at \(x = 2\), \(h(x) = 1.54\); at \(x = 4\), \(h(x) = 1.94\). Which of the following functions best represents this relationship, where \(x \le 4\)?', 'At \(x = 0\), the value is 1.23, which is the coefficient. Over 2 years the height grows by a factor of \(\frac{1.54}{1.23} \approx 1.252\), so the yearly factor is \(\sqrt{1.252} \approx 1.12\). Thus \(h(x) = 1.23(1.12)^x\).', 'mc', '["\\(h(x) = 1.12(0.23)^x\\)","\\(h(x) = 1.12(1.23)^x\\)","\\(h(x) = 1.23(0.12)^x\\)","\\(h(x) = 1.23(1.12)^x\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M1 Q17'),
  ('exp-0026', 'exponential-functions', 'The function \(f\) is defined by \(f(x) = (-8)(2)^x + 22\). What is the \(y\)-intercept of the graph of \(y = f(x)\) in the \(xy\)-plane?', 'At \(x = 0\): \(f(0) = (-8)(2)^0 + 22 = -8 + 22 = 14\), so the \(y\)-intercept is \((0, 14)\).', 'mc', '["\\((0, 14)\\)","\\((0, 2)\\)","\\((0, 22)\\)","\\((0, -8)\\)"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q18'),
  ('exp-0027', 'exponential-functions', 'For the exponential function \(f\), the value of \(f(1)\) is \(k\), where \(k\) is a constant. Which of the following equivalent forms of the function \(f\) shows the value of \(k\) as the coefficient or the base?', 'We need the form where evaluating at \(x = 1\) makes the exponent 0, leaving the coefficient as \(f(1)\). In \(f(x) = 128(1.6)^{x-1}\), \(f(1) = 128(1.6)^0 = 128 = k\), so \(k\) appears directly as the coefficient.', 'mc', '["\\(f(x) = 50(1.6)^{x+1}\\)","\\(f(x) = 80(1.6)^x\\)","\\(f(x) = 128(1.6)^{x-1}\\)","\\(f(x) = 204.8(1.6)^{x-2}\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M2 Q23'),
  ('exp-0028', 'exponential-functions', 'There are 240 players in a tennis competition that includes 4 rounds of matches. Each player in the competition will play a match against another player in round 1. At the end of each round, the player who loses the match is eliminated and the player who won the match advances to the next round to play a match against another winning player. Which equation gives the number of players, \(p\), eliminated at the end of round \(r\), where \(r \le 4\)?', 'Each round eliminates half the players remaining. Starting from 240, the number eliminated at the end of round \(r\) is \(p = 240\left(\frac{1}{2}\right)^r\).', 'mc', '["\\(p = 15\\left(\\frac{1}{2}\\right)^r\\)","\\(p = 15(2)^r\\)","\\(p = 240\\left(\\frac{1}{2}\\right)^r\\)","\\(p = 240(2)^r\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M2 Q11'),
  ('stat-0001', 'data-statistics', 'To estimate the proportion of a population that has a certain characteristic, a random sample was selected from the population. Based on the sample, it is estimated that the proportion of the population that has the characteristic is 0.49, with an associated margin of error of 0.04. Based on this estimate and margin of error, which of the following is the most appropriate conclusion about the proportion of the population that has the characteristic?', 'The plausible range is the estimate plus or minus the margin of error: \(0.49 \pm 0.04\), which is between 0.45 and 0.53.', 'mc', '["It is plausible that the proportion is between 0.45 and 0.53.","It is plausible that the proportion is less than 0.45.","The proportion is exactly 0.49.","It is plausible that the proportion is greater than 0.53."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M2 Q10'),
  ('stat-0002', 'data-statistics', 'A proposal for a new library was included on an election ballot. A radio show stated that 3 times as many people voted in favor of the proposal as people who voted against it. A social media post reported that 15,000 more people voted in favor of the proposal than voted against it. Based on these data, how many people voted against the proposal?', 'Let \(a\) be against votes. Then favor \(= 3a\) and \(3a - a = 15{,}000\), so \(2a = 15{,}000\) and \(a = 7{,}500\).', 'mc', '["7,500","15,000","22,500","45,000"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P4M2 Q15'),
  ('stat-0003', 'data-statistics', 'Scott selected 20 employees at random from all 400 employees at a company. He found that 16 of the employees in this sample are enrolled in exactly three professional development courses this year. Based on Scott''s findings, which of the following is the best estimate of the number of employees at the company who are enrolled in exactly three professional development courses this year?', 'The sample proportion is \(\frac{16}{20} = 0.8\). Applying to 400 employees: \(0.8 \times 400 = 320\).', 'mc', '["4","320","380","384"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q10'),
  ('stat-0004', 'data-statistics', 'At a movie theater, there are a total of 350 customers. Each customer is located in either theater A, theater B, or theater C. If one of these customers is selected at random, the probability of selecting a customer who is located in theater A is 0.48, and the probability of selecting a customer who is located in theater B is 0.24. How many customers are located in theater C?', 'The probability for theater C is \(1 - 0.48 - 0.24 = 0.28\). Number in C \(= 0.28 \times 350 = 98\).', 'mc', '["28","40","84","98"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q12'),
  ('stat-0005', 'data-statistics', 'Five Eretmochelys imbricata, a type of sea turtle, each have a nest. The table shows an original data set of the number of eggs each turtle laid in its nest: 149, 144, 148, 136, 139. A sixth nest with 121 eggs is added to create a new data set. Which of the following correctly compares the means of the two data sets?', 'The added value 121 is below the original mean (about 143.2), so adding it lowers the mean. Thus the original mean is greater than the new mean.', 'mc', '["The mean of the original data set is greater than the mean of the new data set.","The mean of the original data set is less than the mean of the new data set.","The means of both data sets are equal.","There is not enough information to compare the means."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q15'),
  ('stat-0006', 'data-statistics', 'The table shown summarizes the number of employees at each of the 17 restaurants in a town: 2 to 7 employees (2 restaurants), 8 to 13 (4 restaurants), 14 to 19 (2 restaurants), 20 to 25 (7 restaurants), 26 to 31 (2 restaurants). Which of the following could be the median number of employees for the restaurants in this town?', 'With 17 restaurants, the median is the 9th value. Cumulative counts: 2, then 6, then 8, then 15. The 9th value falls in the 20 to 25 group, so the median could be 21.', 'mc', '["2","9","15","21"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q19'),
  ('stat-0007', 'data-statistics', 'On a street with 7 houses, 2 houses are blue. If a house from this street is selected at random, what is the probability of selecting a house that is blue?', 'The probability is the number of blue houses over the total: \(\frac{2}{7}\).', 'mc', '["\\(\\frac{1}{7}\\)","\\(\\frac{2}{7}\\)","\\(\\frac{5}{7}\\)","\\(\\frac{7}{7}\\)"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P6M2 Q3'),
  ('stat-0008', 'data-statistics', '\(4, 10, 18, 4, 4, 5, 6, 5\) What is the median of the data set shown?', 'Sorted: 4, 4, 4, 5, 5, 6, 10, 18. With 8 values, the median is the average of the 4th and 5th: \(\frac{5 + 5}{2} = 5\).', 'mc', '["4","5","7","14"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q15'),
  ('stat-0009', 'data-statistics', 'The bar graph summarizes the charge, in kilowatt-hours (kWh), a battery received each day for 15 days. The charges shown are 0 kWh (6 days), 8 kWh (1 day), 9 kWh (2 days), 11 kWh (4 days), 16 kWh (1 day), and 23 kWh (1 day). For how many of these 15 days did the battery receive a charge of 0 kWh?', 'The bar above 0 kWh reaches 6, so the battery received a charge of 0 kWh on 6 days.', 'mc', '["0","1","4","6"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M1 Q5'),
  ('stat-0010', 'data-statistics', '\(-11, -9, 26\) A data set of three numbers is shown. If a number from this data set is selected at random, what is the probability of selecting a positive number?', 'Only 26 is positive out of the three numbers, so the probability is \(\frac{1}{3}\).', 'mc', '["0","\\(\\frac{1}{3}\\)","\\(\\frac{2}{3}\\)","1"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M2 Q5'),
  ('stat-0011', 'data-statistics', 'For a particular machine that produces beads, 29 out of every 100 beads it produces have a defect. A bead produced by the machine will be selected at random. What is the probability of selecting a bead that has a defect?', 'The probability is the number of defective beads over the total: \(\frac{29}{100}\).', 'mc', '["\\(\\frac{1}{2{,}900}\\)","\\(\\frac{1}{29}\\)","\\(\\frac{29}{100}\\)","\\(\\frac{29}{10}\\)"]'::jsonb, 2, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P8M1 Q2'),
  ('stat-0012', 'data-statistics', 'An analyst collected data on the price of a carton of grape tomatoes at 30 locations selected at random in Utah. The mean price of a carton of grape tomatoes in Utah was estimated to be 4.23 dollars, with an associated margin of error of 0.08 dollars. Which of the following is a plausible statement about the mean price of a carton of grape tomatoes for all locations that sell this product in Utah?', 'The plausible range is the estimate plus or minus the margin of error: \(4.23 \pm 0.08\), which is between 4.15 dollars and 4.31 dollars.', 'mc', '["It is between 4.15 dollars and 4.31 dollars.","It is either less than 4.15 dollars or greater than 4.31 dollars.","It is less than 4.15 dollars.","It is greater than 4.31 dollars."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q5'),
  ('stat-0013', 'data-statistics', 'The frequency table summarizes a data set of the weights, rounded to the nearest pound, of 71 tortoises. The weights and their frequencies are: 13 pounds (12), 14 pounds (8), 15 pounds (5), 16 pounds (7), 17 pounds (9), 18 pounds (10), 19 pounds (13), and 20 pounds (7). A weight of 39 pounds is added to the original data set, creating a new data set of the weights, rounded to the nearest pound, of 72 tortoises. Which statement best compares the mean and median of the new data set to the mean and median of the original data set?', 'The original data has 71 values with mean about 16.55 and median 17. Adding 39, a value well above the original mean, raises the mean to about 16.86. With 72 values, the median is the average of the 36th and 37th ordered values, both of which remain 17, so the median is unchanged. Thus the new mean is greater and the medians are equal.', 'mc', '["The mean of the new data set is greater than the mean of the original data set, and the median of the new data set is greater than the median of the original data set.","The mean of the new data set is greater than the mean of the original data set, and the medians of the two data sets are equal.","The mean of the new data set is less than the mean of the original data set, and the median of the new data set is less than the median of the original data set.","The mean of the new data set is less than the mean of the original data set, and the medians of the two data sets are equal."]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M1 Q23'),
  ('stat-0014', 'data-statistics', 'A poll''s results are shown: Angel Cruz received 483 votes and Terry Smith received 320 votes. A total of 803 voters selected at random were asked which candidate they would vote for in the upcoming election. According to the poll, if 6,424 people vote in the election, by how many votes would Angel Cruz be expected to win?', 'The scaling factor is \(\frac{6{,}424}{803} = 8\). The poll margin is \(483 - 320 = 163\) votes, so the expected margin is \(163 \times 8 = 1{,}304\) votes.', 'mc', '["163","1,304","3,864","5,621"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P9M1 Q26'),
  ('stat-0015', 'data-statistics', 'A table summarizes members of a local organization by age and whether they live east or west of the river. Members less than 40 years old: 17 live east, 11 live west (28 total). Members at least 40 years old: 18 live east, 89 live west (107 total). The totals are 35 east, 100 west, and 135 overall. If a member of the organization is selected at random, what is the probability that the selected member is at least 40 years old?', 'There are 107 members at least 40 years old out of 135 total, so the probability is \(\frac{107}{135}\).', 'mc', '["\\(\\frac{28}{135}\\)","\\(\\frac{35}{135}\\)","\\(\\frac{100}{135}\\)","\\(\\frac{107}{135}\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q3'),
  ('stat-0016', 'data-statistics', 'A table gives the distribution of votes for a new school mascot and grade level for 80 students. The counts by mascot (sixth, seventh, eighth, total) are: Badger 4, 9, 9, 22; Lion 9, 2, 9, 20; Longhorn 4, 6, 4, 14; Tiger 6, 9, 9, 24; and the column totals are 23, 26, 31, 80. If one of these students is selected at random, what is the probability of selecting a student whose vote for new mascot was for a lion?', 'The lion total is 20 out of 80 students, so the probability is \(\frac{20}{80} = \frac{1}{4}\).', 'mc', '["\\(\\frac{1}{9}\\)","\\(\\frac{1}{5}\\)","\\(\\frac{1}{4}\\)","\\(\\frac{2}{3}\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q8'),
  ('stat-0017', 'data-statistics', 'A total of 50 children attended a summer camp and were offered 4 types of sandwiches. A table shows the number of children who chose each type of sandwich: Turkey 15, Chicken 23, Ham 3, Vegetarian 9, for a total of 50. If one of these children is selected at random, what is the probability of selecting a child who chose a vegetarian sandwich?', '9 of the 50 children chose vegetarian, so the probability is \(\frac{9}{50}\).', 'mc', '["\\(\\frac{9}{100}\\)","\\(\\frac{9}{50}\\)","\\(\\frac{1}{4}\\)","\\(\\frac{9}{10}\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q5'),
  ('stat-0018', 'data-statistics', 'A cable provider wanted to know how many of its 30,000 customers would be interested in a new service plan. The provider selected 300 customers at random and asked each customer whether the customer would be interested in the new plan. Of those surveyed, 8 said they would be interested. Which of the following is the best estimate of the total number of customers who would be interested in the new service plan?', 'The sample proportion is \(\frac{8}{300}\). Applied to 30,000 customers: \(\frac{8}{300} \times 30{,}000 = 800\).', 'mc', '["8","80","800","8,000"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q10'),
  ('stat-0019', 'data-statistics', 'A scientist measured the lengths of 240 gray seals from Muskeget Island and 120 gray seals from Sable Island. The scientist determined that the mean length of the 240 gray seals from Muskeget Island was 88 inches and the mean length of the 120 gray seals from Sable Island was 94 inches. What was the mean length of all 360 gray seals the scientist measured for this study?', 'The combined mean is the weighted average: \(\frac{240(88) + 120(94)}{360} = \frac{21{,}120 + 11{,}280}{360} = \frac{32{,}400}{360} = 90\) inches.', 'mc', '["89","90","91","92"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P11M1 Q22'),
  ('geo-0001', 'geometry-trigonometry', 'For a certain rectangular region, the ratio of its length to its width is 35 to 10. If the width of the rectangular region increases by 7 units, how must the length change to maintain this ratio?', 'The ratio length:width is \(35:10 = 3.5\). If width increases by 7, length must increase by \(3.5 \times 7 = 24.5\) units to keep the ratio.', 'mc', '["It must decrease by 24.5 units.","It must increase by 24.5 units.","It must decrease by 7 units.","It must increase by 7 units."]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P4M1 Q17'),
  ('geo-0002', 'geometry-trigonometry', 'A right triangle has sides of length \(2\sqrt{2}\), \(6\sqrt{2}\), and \(\sqrt{80}\) units. What is the area of the triangle, in square units?', 'The legs are \(2\sqrt{2}\) and \(6\sqrt{2}\) (since \((2\sqrt2)^2 + (6\sqrt2)^2 = 8 + 72 = 80 = (\sqrt{80})^2\), so \(\sqrt{80}\) is the hypotenuse). Area \(= \frac{1}{2}(2\sqrt2)(6\sqrt2) = \frac{1}{2}(12 \cdot 2) = 12\).', 'mc', '["\\(8\\sqrt{2} + \\sqrt{80}\\)","12","\\(24\\sqrt{80}\\)","24"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, TRUE, 'P4M1 Q22'),
  ('geo-0003', 'geometry-trigonometry', 'An isosceles right triangle has a hypotenuse of length 58 inches. What is the perimeter, in inches, of this triangle?', 'In a 45-45-90 triangle, each leg is \(\frac{58}{\sqrt2} = 29\sqrt2\). Perimeter \(= 58 + 2(29\sqrt2) = 58 + 58\sqrt2\).', 'mc', '["\\(29\\sqrt{2}\\)","\\(58\\sqrt{2}\\)","\\(58 + 58\\sqrt{2}\\)","\\(58 + 116\\sqrt{2}\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M1 Q25'),
  ('geo-0004', 'geometry-trigonometry', 'The equation \(x^2 + (y - 1)^2 = 49\) represents circle A. Circle B is obtained by shifting circle A down 2 units in the \(xy\)-plane. Which of the following equations represents circle B?', 'Circle A has center \((0, 1)\). Shifting down 2 units gives center \((0, -1)\), so the equation becomes \(x^2 + (y + 1)^2 = 49\).', 'mc', '["\\((x - 2)^2 + (y - 1)^2 = 49\\)","\\(x^2 + (y - 3)^2 = 49\\)","\\((x + 2)^2 + (y - 1)^2 = 49\\)","\\(x^2 + (y + 1)^2 = 49\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M2 Q25'),
  ('geo-0005', 'geometry-trigonometry', 'Two identical rectangular prisms each have a height of 90 centimeters (cm). The base of each prism is a square, and the surface area of each prism is \(K\) cm\(^2\). If the prisms are glued together along a square base, the resulting prism has a surface area of \(\frac{92}{47}K\) cm\(^2\). What is the side length, in cm, of each square base?', 'Let \(s\) be the side. Each prism: \(K = 2s^2 + 4s(90) = 2s^2 + 360s\). Glued: two squares hidden, surface area \(= 2K - 2s^2 = 4s^2 + 720s - 2s^2 = 2s^2 + 720s\). Setting \(2s^2 + 720s = \frac{92}{47}(2s^2 + 360s)\) and solving gives \(s = 8\).', 'mc', '["4","8","9","16"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P4M2 Q26'),
  ('geo-0006', 'geometry-trigonometry', 'In the figure, line \(m\) is parallel to line \(n\), and line \(k\) intersects both lines. The angle marked \(x^\circ\) and the angle marked \(145^\circ\) are shown at the intersection with line \(n\). Which of the following statements is true?', 'The angle \(x^\circ\) and the \(145^\circ\) angle are vertical angles at the same intersection, so they are equal: \(x = 145\).', 'mc', '["The value of \\(x\\) is less than 145.","The value of \\(x\\) is greater than 145.","The value of \\(x\\) is equal to 145.","The value of \\(x\\) cannot be determined."]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q8'),
  ('geo-0007', 'geometry-trigonometry', 'A right circular cylinder has a base diameter of 22 centimeters and a height of 6 centimeters. What is the volume, in cubic centimeters, of the cylinder?', 'The radius is \(22 \div 2 = 11\). Volume \(= \pi r^2 h = \pi (11)^2 (6) = \pi (121)(6) = 726\pi\).', 'mc', '["\\(132\\pi\\)","\\(264\\pi\\)","\\(726\\pi\\)","\\(2{,}904\\pi\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q15'),
  ('geo-0008', 'geometry-trigonometry', 'What is the value of \(\tan \frac{92\pi}{3}\)?', '\(\frac{92\pi}{3} = 30\pi + \frac{2\pi}{3}\), which is coterminal with \(\frac{2\pi}{3}\) (since \(30\pi\) is an integer multiple of \(\pi\), and tangent has period \(\pi\), the angle reduces to \(\frac{2\pi}{3}\)). \(\tan\frac{2\pi}{3} = -\sqrt{3}\).', 'mc', '["\\(-\\sqrt{3}\\)","\\(-\\frac{\\sqrt{3}}{3}\\)","\\(\\frac{\\sqrt{3}}{3}\\)","\\(\\sqrt{3}\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M1 Q19'),
  ('geo-0009', 'geometry-trigonometry', '\((x + 4)^2 + (y - 19)^2 = 121\) The graph of the given equation is a circle in the \(xy\)-plane. The point \((a, b)\) lies on the circle. Which of the following is a possible value for \(a\)?', 'The circle has center \((-4, 19)\) and radius \(\sqrt{121} = 11\). The \(x\)-values on the circle range from \(-4 - 11 = -15\) to \(-4 + 11 = 7\). Only \(-14\) falls in this range.', 'mc', '["-16","-14","11","19"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M1 Q22'),
  ('geo-0010', 'geometry-trigonometry', 'In triangle \(RST\), the measure of angle \(R\) is 63 degrees. Which of the following could be the measure, in degrees, of angle \(S\)?', 'The angles of a triangle sum to 180 degrees, so angle \(S\) must be less than \(180 - 63 = 117\) degrees (leaving room for angle \(T\)). Only 116 is less than 117.', 'mc', '["116","118","126","180"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P5M2 Q16'),
  ('geo-0011', 'geometry-trigonometry', 'Rectangles \(ABCD\) and \(EFGH\) are similar. The length of each side of \(EFGH\) is 6 times the length of the corresponding side of \(ABCD\). The area of \(ABCD\) is 54 square units. What is the area, in square units, of \(EFGH\)?', 'For similar figures, area scales by the square of the linear ratio: \(6^2 = 36\). So area of \(EFGH = 54 \times 36 = 1{,}944\).', 'mc', '["9","36","324","1,944"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M2 Q22'),
  ('geo-0012', 'geometry-trigonometry', 'A circle in the \(xy\)-plane has its center at \((-1, 1)\). Line \(t\) is tangent to this circle at the point \((5, -4)\). Which of the following points also lies on line \(t\)?', 'The radius from \((-1, 1)\) to \((5, -4)\) has slope \(\frac{-4 - 1}{5 + 1} = -\frac{5}{6}\). The tangent is perpendicular, with slope \(\frac{6}{5}\). Line \(t\): \(y + 4 = \frac{6}{5}(x - 5)\). Testing \((10, 2)\): \(2 + 4 = 6\) and \(\frac{6}{5}(10 - 5) = 6\) ✓.', 'mc', '["\\(\\left(0, \\frac{6}{5}\\right)\\)","\\((4, 7)\\)","\\((10, 2)\\)","\\((11, 1)\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P5M2 Q26'),
  ('geo-0013', 'geometry-trigonometry', 'Circle \(A\) (shown) is defined by the equation \((x + 2)^2 + y^2 = 9\). Circle \(B\) (not shown) is the result of shifting circle \(A\) down 6 units and increasing the radius so that the radius of circle \(B\) is 2 times the radius of circle \(A\). Which equation defines circle \(B\)?', 'Shifting down 6 changes center from \((-2, 0)\) to \((-2, -6)\), giving \((y + 6)^2\). Doubling the radius (from 3 to 6) makes \(r^2 = 36 = (4)(9)\). So \((x+2)^2 + (y+6)^2 = (4)(9)\).', 'mc', '["\\((x + 2)^2 + (y + 6)^2 = (4)(9)\\)","\\(2(x + 2)^2 + 2(y + 6)^2 = 9\\)","\\((x + 2)^2 + (y - 6)^2 = (4)(9)\\)","\\(2(x + 2)^2 + 2(y - 6)^2 = 9\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M1 Q23'),
  ('geo-0014', 'geometry-trigonometry', 'Right triangle \(ABC\) is shown, with the right angle at \(C\), hypotenuse \(AB = 54\), and the angle at \(B\) equal to 30 degrees. What is the value of \(\tan A\)?', 'Since angle \(C = 90^\circ\) and angle \(B = 30^\circ\), angle \(A = 60^\circ\). \(\tan 60^\circ = \sqrt{3}\).', 'mc', '["\\(\\frac{\\sqrt{3}}{54}\\)","\\(\\frac{1}{\\sqrt{3}}\\)","\\(\\sqrt{3}\\)","\\(27\\sqrt{3}\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M1 Q24'),
  ('geo-0015', 'geometry-trigonometry', 'In the figure, two lines intersect at a point. Angle 1 and angle 2 are vertical angles. The measure of angle 1 is 72 degrees. What is the measure of angle 2?', 'Vertical angles are equal, so angle 2 equals angle 1, which is 72 degrees.', 'mc', '["72 degrees","108 degrees","144 degrees","288 degrees"]'::jsonb, 0, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P6M2 Q2'),
  ('geo-0016', 'geometry-trigonometry', 'A right circular cylinder has a volume of 432 cubic centimeters. The area of the base of the cylinder is 24 square centimeters. What is the height, in centimeters, of the cylinder?', 'Volume = base area times height, so height \(= \frac{432}{24} = 18\) centimeters.', 'mc', '["18","24","216","10,368"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P6M2 Q16'),
  ('geo-0017', 'geometry-trigonometry', 'In triangle \(ABC\), angle \(B\) is a right angle. The length of side \(AB\) is \(10\sqrt{37}\) and the length of side \(BC\) is \(24\sqrt{37}\). What is the length of side \(AC\)?', 'By the Pythagorean theorem, \(AC = \sqrt{(10\sqrt{37})^2 + (24\sqrt{37})^2} = \sqrt{37(100 + 576)} = \sqrt{37 \cdot 676} = 26\sqrt{37}\).', 'mc', '["\\(14\\sqrt{37}\\)","\\(26\\sqrt{37}\\)","\\(34\\sqrt{37}\\)","\\(\\sqrt{34 \\cdot 37}\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M2 Q22'),
  ('geo-0018', 'geometry-trigonometry', 'In the \(xy\)-plane, a circle has center \(C\) with coordinates \((h, k)\). Points \(A\) and \(B\) lie on the circle. Point \(A\) has coordinates \((h + 1, k + \sqrt{102})\), and angle \(ACB\) is a right angle. What is the length of \(\overline{AB}\)?', 'The radius is \(CA = \sqrt{1^2 + (\sqrt{102})^2} = \sqrt{103}\). Since angle \(ACB\) is right and \(CA = CB = \sqrt{103}\), \(AB = \sqrt{103}\cdot\sqrt{2} = \sqrt{206}\).', 'mc', '["\\(\\sqrt{206}\\)","\\(2\\sqrt{102}\\)","\\(103\\sqrt{2}\\)","\\(103\\sqrt{3}\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P6M2 Q25'),
  ('geo-0019', 'geometry-trigonometry', 'Triangles \(EFG\) and \(JKL\) are congruent, where \(E\), \(F\), and \(G\) correspond to \(J\), \(K\), and \(L\), respectively. The measure of angle \(E\) is 45 degrees and the measure of angle \(F\) is 20 degrees. What is the measure of angle \(J\)?', 'In congruent triangles, corresponding angles are equal. Angle \(J\) corresponds to angle \(E\), which is 45 degrees.', 'mc', '["20 degrees","45 degrees","135 degrees","160 degrees"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P7M1 Q9'),
  ('geo-0020', 'geometry-trigonometry', 'A circle in the \(xy\)-plane has the equation \((x - 13)^2 + (y - k)^2 = 64\). Which of the following gives the center of the circle and its radius?', 'In standard form \((x - h)^2 + (y - k)^2 = r^2\), the center is \((13, k)\) and the radius is \(\sqrt{64} = 8\).', 'mc', '["The center is at \\((13, k)\\) and the radius is 8.","The center is at \\((k, 13)\\) and the radius is 8.","The center is at \\((k, 13)\\) and the radius is 64.","The center is at \\((13, k)\\) and the radius is 64."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M1 Q15'),
  ('geo-0021', 'geometry-trigonometry', 'Points \(Q\) and \(R\) lie on a circle with center \(P\). The radius of this circle is 9 inches. Triangle \(PQR\) has a perimeter of 31 inches. What is the length, in inches, of \(\overline{QR}\)?', 'Sides \(PQ\) and \(PR\) are radii, each 9 inches. The perimeter is \(9 + 9 + QR = 31\), so \(QR = 31 - 18 = 13\) inches.', 'mc', '["\\(13\\sqrt{2}\\)","13","\\(9\\sqrt{2}\\)","9"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M1 Q22'),
  ('geo-0022', 'geometry-trigonometry', 'Which of the following expressions is equivalent to \((\sin 24^\circ)(\cos 66^\circ) + (\cos 24^\circ)(\sin 66^\circ)\)?', 'Since \(\sin 24^\circ = \cos 66^\circ\) and \(\sin 66^\circ = \cos 24^\circ\) (complementary angles), the expression becomes \((\cos 66^\circ)(\cos 66^\circ) + (\cos 24^\circ)(\cos 24^\circ) = (\cos 66^\circ)^2 + (\cos 24^\circ)^2\).', 'mc', '["\\(2(\\cos 66^\\circ)(\\sin 24^\\circ)\\)","\\(2(\\cos 66^\\circ) + 2(\\cos 24^\\circ)\\)","\\((\\cos 66^\\circ)^2 + (\\cos 24^\\circ)^2\\)","\\((\\cos 66^\\circ)^2 + (\\sin 24^\\circ)^2\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M1 Q25'),
  ('geo-0023', 'geometry-trigonometry', 'An investment account was opened with an initial value of 890 dollars. The value of the account doubled every 10 years. Which equation represents the value of the account \(M(t)\), in dollars, \(t\) years after the account was opened?', 'Doubling every 10 years means a growth factor of 2 with exponent \(\frac{t}{10}\): \(M(t) = 890(2)^{\frac{t}{10}}\).', 'mc', '["\\(M(t) = 890\\left(\\frac{1}{2}\\right)^{\\frac{t}{10}}\\)","\\(M(t) = 890\\left(\\frac{1}{10}\\right)^{\\frac{t}{2}}\\)","\\(M(t) = 890(2)^{\\frac{t}{10}}\\)","\\(M(t) = 890(10)^{\\frac{t}{2}}\\)"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P7M2 Q15'),
  ('geo-0024', 'geometry-trigonometry', 'In triangle \(XYZ\), angle \(Z\) is a right angle and the length of \(\overline{YZ}\) is 24 units. If \(\tan X = \frac{12}{35}\), what is the perimeter, in units, of triangle \(XYZ\)?', '\(\tan X = \frac{\text{opposite}}{\text{adjacent}} = \frac{YZ}{XZ} = \frac{12}{35}\). With \(YZ = 24 = 2 \times 12\), scale factor 2 gives \(XZ = 70\) and hypotenuse \(XY = 2 \times 37 = 74\). Perimeter \(= 24 + 70 + 74 = 168\).', 'mc', '["188","168","84","71"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M2 Q24'),
  ('geo-0025', 'geometry-trigonometry', '\(x^2 + 14x + y^2 = 6y + 109\) In the \(xy\)-plane, the graph of the given equation is a circle. What is the length of the circle''s radius?', 'Complete the square: \((x^2 + 14x + 49) + (y^2 - 6y + 9) = 109 + 49 + 9 = 167\), giving \((x+7)^2 + (y-3)^2 = 167\). The radius is \(\sqrt{167}\).', 'mc', '["\\(\\sqrt{109}\\)","\\(\\sqrt{149}\\)","\\(\\sqrt{167}\\)","\\(\\sqrt{341}\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P7M2 Q25'),
  ('geo-0026', 'geometry-trigonometry', 'Right triangles \(LMN\) and \(PQR\) are similar, where \(L\) and \(M\) correspond to \(P\) and \(Q\), respectively. Angle \(M\) has a measure of 53 degrees. What is the measure of angle \(Q\)?', 'In similar triangles, corresponding angles are equal. Since \(M\) corresponds to \(Q\), angle \(Q\) also measures 53 degrees.', 'mc', '["37 degrees","53 degrees","127 degrees","143 degrees"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M1 Q9'),
  ('geo-0027', 'geometry-trigonometry', 'Circle \(A\) has a radius of \(3n\) and circle \(B\) has a radius of \(129n\), where \(n\) is a positive constant. The area of circle \(B\) is how many times the area of circle \(A\)?', 'The ratio of areas equals the square of the ratio of radii: \(\left(\frac{129n}{3n}\right)^2 = 43^2 = 1{,}849\).', 'mc', '["43","86","129","1,849"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M1 Q18'),
  ('geo-0028', 'geometry-trigonometry', 'The measure of angle \(R\) is \(\frac{2\pi}{3}\) radians. The measure of angle \(T\) is \(\frac{5\pi}{12}\) radians greater than the measure of angle \(R\). What is the measure of angle \(T\), in degrees?', 'Angle \(T = \frac{2\pi}{3} + \frac{5\pi}{12} = \frac{8\pi}{12} + \frac{5\pi}{12} = \frac{13\pi}{12}\) radians. Converting: \(\frac{13\pi}{12} \times \frac{180}{\pi} = 195\) degrees.', 'mc', '["75","120","195","390"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M1 Q19'),
  ('geo-0029', 'geometry-trigonometry', 'In the figure, line \(m\) is parallel to line \(n\), and line \(t\) intersects both lines. The angle \(x^\circ\) is formed where \(t\) crosses \(m\), and a \(33^\circ\) angle is formed where \(t\) crosses \(n\). What is the value of \(x\)?', 'The \(33^\circ\) angle and \(x^\circ\) are same-side (co-interior) supplementary angles along the transversal, so \(x = 180 - 33 = 147\).', 'mc', '["33","57","123","147"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q3'),
  ('geo-0030', 'geometry-trigonometry', 'For the right triangle shown, with legs \(a\) and \(b\) and hypotenuse \(c\), \(a = 4\) and \(b = 5\). Which expression represents the value of \(c\)?', 'By the Pythagorean theorem, \(c = \sqrt{a^2 + b^2} = \sqrt{4^2 + 5^2}\).', 'mc', '["\\(4 + 5\\)","\\(\\sqrt{(4)(5)}\\)","\\(\\sqrt{4 + 5}\\)","\\(\\sqrt{4^2 + 5^2}\\)"]'::jsonb, 3, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q5'),
  ('geo-0031', 'geometry-trigonometry', 'In the right triangle shown, with the right angle at \(C\), side \(35\) is opposite \(A\) and hypotenuse \(171\) is opposite \(C\). What is the value of \(\sin A\)?', '\(\sin A\) equals the side opposite angle \(A\) over the hypotenuse: \(\frac{35}{171}\).', 'mc', '["\\(\\frac{1}{171}\\)","\\(\\frac{35}{171}\\)","\\(\\frac{171}{35}\\)","171"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P8M2 Q12'),
  ('geo-0032', 'geometry-trigonometry', 'A cube has an edge length of 68 inches. A solid sphere with a radius of 34 inches is inside the cube, such that the sphere touches the center of each face of the cube. To the nearest cubic inch, what is the volume of the space in the cube not taken up by the sphere?', 'Cube volume \(= 68^3 = 314{,}432\). Sphere volume \(= \frac{4}{3}\pi(34)^3 \approx 164{,}636\). The remaining space \(\approx 314{,}432 - 164{,}636 = 149{,}796\).', 'mc', '["149,796","164,500","190,955","310,800"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M2 Q22'),
  ('geo-0033', 'geometry-trigonometry', 'Triangles \(PQR\) and \(LMN\) are graphed in the \(xy\)-plane. Triangle \(PQR\) has vertices \(P\), \(Q\), and \(R\) at \((4, 5)\), \((4, 7)\), and \((6, 5)\), respectively. Triangle \(LMN\) has vertices \(L\), \(M\), and \(N\) at \((4, 5)\), \((4, 7 + k)\), and \((6 + k, 5)\), respectively, where \(k\) is a positive constant. If the measure of angle \(Q\) is \(t^\circ\), what is the measure of angle \(N\)?', 'Both triangles are right triangles with the right angle at the vertex \((4,5)\) (\(P\) and \(L\)). The three angles sum to 180, so angle \(N = 90 - \text{angle } M\). Since \(PQR\) and \(LMN\) share the same right-angle configuration and angle \(M\) corresponds to angle \(Q = t^\circ\), angle \(N = (90 - t)^\circ\).', 'mc', '["\\((90 - (t - k))^\\circ\\)","\\((90 - (t + k))^\\circ\\)","\\((90 - t)^\\circ\\)","\\((90 + k)^\\circ\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P8M2 Q24'),
  ('geo-0034', 'geometry-trigonometry', 'The lengths of two sides of a triangle are 4 centimeters and 6 centimeters. If the perimeter of the triangle is 18 centimeters, what is the length, in centimeters, of the third side of this triangle?', 'The third side is the perimeter minus the other two sides: \(18 - 4 - 6 = 8\) centimeters.', 'mc', '["2","8","10","24"]'::jsonb, 1, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P9M1 Q1'),
  ('geo-0035', 'geometry-trigonometry', 'A circle with center \(O\) has circumference \(144\pi\) and diameters \(\overline{PR}\) and \(\overline{QS}\). The length of arc \(PS\) is twice the length of arc \(PQ\). What is the length of arc \(QR\)?', 'Since \(\overline{PR}\) and \(\overline{QS}\) are diameters, arcs \(PQ\) and \(SR\) are equal, and arcs \(PS\) and \(QR\) are equal (vertical arcs). Arcs \(PS\) and \(PQ\) together make a semicircle: arc \(PS\) + arc \(PQ\) = \(\frac{1}{2}(144\pi) = 72\pi\). With arc \(PS\) = 2(arc \(PQ\)), we get \(3(\text{arc } PQ) = 72\pi\), so arc \(PQ = 24\pi\) and arc \(PS = 48\pi\). Arc \(QR\) equals arc \(PS = 48\pi\).', 'mc', '["\\(24\\pi\\)","\\(48\\pi\\)","\\(72\\pi\\)","\\(96\\pi\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P9M1 Q12'),
  ('geo-0036', 'geometry-trigonometry', 'One leg of a right triangle has a length of 43.2 millimeters. The hypotenuse of the triangle has a length of 196.8 millimeters. What is the length of the other leg of the triangle, in millimeters?', 'By the Pythagorean theorem, the other leg is \(\sqrt{196.8^2 - 43.2^2} = \sqrt{38{,}730.24 - 1{,}866.24} = \sqrt{36{,}864} = 192\) millimeters.', 'mc', '["43.2","120","192","201.5"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M1 Q15'),
  ('geo-0037', 'geometry-trigonometry', 'Triangle \(FGH\) is similar to triangle \(JKL\), where angle \(F\) corresponds to angle \(J\) and angles \(G\) and \(K\) are right angles. If \(\sin(F) = \frac{308}{317}\), what is the value of \(\sin(J)\)?', 'In similar triangles, corresponding angles are equal, so \(\sin(J) = \sin(F) = \frac{308}{317}\).', 'mc', '["\\(\\frac{75}{317}\\)","\\(\\frac{308}{317}\\)","\\(\\frac{317}{308}\\)","\\(\\frac{317}{75}\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q15'),
  ('geo-0038', 'geometry-trigonometry', 'Triangle \(XYZ\) is similar to triangle \(RST\) such that \(X\), \(Y\), and \(Z\) correspond to \(R\), \(S\), and \(T\), respectively. The measure of angle \(Z\) is 20 degrees and \(2XY = RS\). What is the measure of angle \(T\)?', 'In similar triangles, corresponding angles are equal regardless of scale factor. Since \(Z\) corresponds to \(T\), angle \(T\) = angle \(Z\) = 20 degrees.', 'mc', '["2 degrees","10 degrees","20 degrees","40 degrees"]'::jsonb, 2, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P9M2 Q19'),
  ('geo-0039', 'geometry-trigonometry', 'A square is inscribed in a circle. The radius of the circle is \(\frac{20\sqrt{2}}{2}\) inches. What is the side length, in inches, of the square?', 'The diagonal of the inscribed square equals the circle''s diameter: \(2 \times \frac{20\sqrt2}{2} = 20\sqrt2\). For a square, side = diagonal \(\div \sqrt2 = \frac{20\sqrt2}{\sqrt2} = 20\) inches.', 'mc', '["20","\\(\\frac{20\\sqrt{2}}{2}\\)","\\(20\\sqrt{2}\\)","40"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, TRUE, 'P9M2 Q24'),
  ('geo-0040', 'geometry-trigonometry', 'Triangles \(ABC\) and \(DEF\) are congruent, where \(A\) corresponds to \(D\), and \(B\) and \(E\) are right angles. The measure of angle \(A\) is 18 degrees. What is the measure of angle \(F\)?', 'In triangle \(DEF\), angle \(E\) is 90 degrees and angle \(D\) equals angle \(A\) = 18 degrees (corresponding parts). So angle \(F = 180 - 90 - 18 = 72\) degrees.', 'mc', '["18 degrees","72 degrees","90 degrees","162 degrees"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q9'),
  ('geo-0041', 'geometry-trigonometry', 'The function \(f(w) = 6w^2\) gives the area of a rectangle, in square feet (ft²), if its width is \(w\) ft and its length is 6 times its width. Which of the following is the best interpretation of \(f(14) = 1{,}176\)?', 'The input to \(f\) is the width and the output is the area. So \(f(14) = 1{,}176\) means a width of 14 ft gives an area of 1,176 ft².', 'mc', '["If the width of the rectangle is 14 ft, then the area of the rectangle is 1,176 ft².","If the width of the rectangle is 14 ft, then the length of the rectangle is 1,176 ft.","If the width of the rectangle is 1,176 ft, then the length of the rectangle is 14 ft.","If the width of the rectangle is 1,176 ft, then the area of the rectangle is 14 ft²."]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q15'),
  ('geo-0042', 'geometry-trigonometry', 'The floor of a ballroom has an area of 600 square meters. An architect creates a scale model of the floor of the ballroom, where the length of each side of the model is \(\frac{1}{10}\) times the length of the corresponding side of the actual floor of the ballroom. What is the area, in square meters, of the scale model?', 'Scaling each linear dimension by \(\frac{1}{10}\) scales the area by \(\left(\frac{1}{10}\right)^2 = \frac{1}{100}\). So the model''s area is \(600 \times \frac{1}{100} = 6\) square meters.', 'mc', '["6","10","60","150"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M1 Q22'),
  ('geo-0043', 'geometry-trigonometry', 'Which of the following equations represents a circle in the \(xy\)-plane that intersects the \(y\)-axis at exactly one point?', 'A circle intersects the \(y\)-axis at exactly one point when it is tangent to it, meaning the distance from the center to the \(y\)-axis equals the radius. The radius is \(\sqrt{16} = 4\). For \((x - 4)^2 + (y - 9)^2 = 16\), the center is \((4, 9)\) and its distance to the \(y\)-axis is 4, equal to the radius, so it is tangent.', 'mc', '["\\((x - 8)^2 + (y - 8)^2 = 16\\)","\\((x - 8)^2 + (y - 4)^2 = 16\\)","\\((x - 4)^2 + (y - 9)^2 = 16\\)","\\(x^2 + (y - 9)^2 = 16\\)"]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M1 Q23'),
  ('geo-0044', 'geometry-trigonometry', 'In triangles \(ABC\) and \(DEF\), angles \(B\) and \(E\) each have measure 27 degrees and angles \(C\) and \(F\) each have measure 41 degrees. Which additional piece of information is sufficient to determine whether triangle \(ABC\) is congruent to triangle \(DEF\)?', 'The triangles are already similar (two pairs of equal angles). To establish congruence, a pair of corresponding sides must be known to be equal. Knowing the lengths of corresponding sides \(BC\) and \(EF\) allows checking whether they are equal, which determines congruence.', 'mc', '["The measure of angle \\(A\\)","The length of side \\(AB\\)","The lengths of sides \\(BC\\) and \\(EF\\)","No additional information is necessary."]'::jsonb, 2, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P10M1 Q24'),
  ('geo-0045', 'geometry-trigonometry', 'What is the perimeter, in inches, of a rectangle with a length of 4 inches and a width of 9 inches?', 'The perimeter is \(2(\text{length} + \text{width}) = 2(4 + 9) = 26\) inches.', 'mc', '["13","17","22","26"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, FALSE, 'P10M2 Q4'),
  ('geo-0046', 'geometry-trigonometry', 'Each side of equilateral triangle S is multiplied by a scale factor of \(k\) to create equilateral triangle T. The length of each side of triangle T is greater than the length of each side of triangle S. Which of the following could be the value of \(k\)?', 'For triangle T''s sides to be longer, the scale factor must be greater than 1. Only \(\frac{29}{28} > 1\).', 'mc', '["\\(\\frac{29}{28}\\)","1","\\(\\frac{28}{29}\\)","0"]'::jsonb, 0, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q11'),
  ('geo-0047', 'geometry-trigonometry', 'In right triangle \(RST\), the sum of the measures of angle \(R\) and angle \(S\) is 90 degrees. The value of \(\sin(R)\) is \(\frac{\sqrt{15}}{4}\). What is the value of \(\cos(S)\)?', 'Since \(R\) and \(S\) are complementary (sum to 90 degrees), \(\cos(S) = \sin(R) = \frac{\sqrt{15}}{4}\).', 'mc', '["\\(\\frac{\\sqrt{15}}{15}\\)","\\(\\frac{\\sqrt{15}}{4}\\)","\\(\\frac{4\\sqrt{15}}{15}\\)","\\(\\sqrt{15}\\)"]'::jsonb, 1, NULL, 'medium', 1.0, 0.0, 0.25, FALSE, 'P10M2 Q15'),
  ('geo-0048', 'geometry-trigonometry', 'In right triangle \(QRS\), the right angle is at \(R\), side \(SR\) has length 18, and \(QR < RS\). Which expression represents the length of \(\overline{QS}\)?', 'In the right triangle, side 18 is opposite angle \(Q\), and \(\overline{QS}\) is the hypotenuse. Since \(\sin Q = \frac{\text{opposite}}{\text{hypotenuse}} = \frac{18}{QS}\), solving gives \(QS = \frac{18}{\sin Q}\).', 'mc', '["\\(18\\cos Q\\)","\\(18\\sin Q\\)","\\(\\frac{18}{\\cos Q}\\)","\\(\\frac{18}{\\sin Q}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M1 Q19'),
  ('geo-0049', 'geometry-trigonometry', 'Two lines intersect at exactly one point, forming two acute angles and two obtuse angles. The measure of one of these angles is \((9x - 140)^\circ\). Which of the following could NOT be the sum of the measures of any two of these angles?', 'Let the given angle be \(9x - 140\); its supplement is \(180 - (9x - 140) = 320 - 9x\). The possible sums of two angles are: two equal acute angles \(2(9x - 140) = 18x - 280\) (option C), two equal obtuse angles \(2(320 - 9x) = -18x + 640\) (option B), or one of each \(180\) (option D). The value \(-18x + 280\) cannot arise, so it is the answer.', 'mc', '["\\((-18x + 280)^\\circ\\)","\\((-18x + 640)^\\circ\\)","\\((18x - 280)^\\circ\\)","\\(180^\\circ\\)"]'::jsonb, 0, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M1 Q24'),
  ('geo-0050', 'geometry-trigonometry', 'A right rectangular prism has a base area of \(24t\) square centimeters (cm²). The length of the base of the rectangular prism is \(\frac{8}{3}\) cm, and the height of the rectangular prism is 15 cm. Which expression represents the surface area, in cm², of the right rectangular prism?', 'The base width is \(\frac{24t}{8/3} = 9t\) cm. Surface area \(= 2(\ell w) + 2(\ell h) + 2(w h) = 2(24t) + 2\left(\frac{8}{3}\cdot 15\right) + 2(9t \cdot 15) = 48t + 80 + 270t = 318t + 80\).', 'mc', '["\\(48t + 160\\)","\\(318t + 80\\)","\\(1{,}968t + 80\\)","\\(360t\\)"]'::jsonb, 1, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M1 Q26'),
  ('geo-0051', 'geometry-trigonometry', 'A rectangle has a length of 56 inches and a width of 28 inches. What is the area, in square inches, of the rectangle?', 'The area of a rectangle is length times width: \(56 \times 28 = 1{,}568\) square inches.', 'mc', '["28","84","168","1,568"]'::jsonb, 3, NULL, 'easy', 1.0, -1.0, 0.25, TRUE, 'P11M2 Q3'),
  ('geo-0052', 'geometry-trigonometry', 'In triangle \(XYZ\), the measure of angle \(X\) is 90 degrees. Point \(W\) lies on segment \(YZ\), and segment \(WX\) is perpendicular to segment \(YZ\). The length of segment \(WY\) is 572, and the length of segment \(WX\) is 429. What is the value of \(\tan Z\)?', 'The altitude to the hypotenuse gives \(WX^2 = WY \cdot WZ\), so \(WZ = \frac{429^2}{572} = 321.75\). In right triangle \(WXZ\), \(\tan Z = \frac{WX}{WZ} = \frac{429}{321.75} = \frac{4}{3}\).', 'mc', '["\\(\\frac{3}{5}\\)","\\(\\frac{3}{4}\\)","\\(\\frac{4}{5}\\)","\\(\\frac{4}{3}\\)"]'::jsonb, 3, NULL, 'hard', 1.0, 1.0, 0.25, FALSE, 'P11M2 Q26');
